/* Generated from the teacher handouts for Sessions 2 and 8-19. Practice questions are original; answer keys come from the handouts' teacher keys. */
(function(){"use strict";Object.assign(window.estLessons,{"sentences-fragments":{"session":8,"kind":"Grammar","title":"Sentences and Fragments","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 71","goal":"A complete sentence expresses a complete thought. It usually contains a subject and a finite verb and can stand independently.","sections":[{"h":"","blocks":[{"t":"p","x":"A complete sentence: expresses a complete thought and contains an independent clause: a subject + a finite verb, with no unfinished dependent-clause structure."},{"t":"p","x":"A fragment: looks like a sentence but leaves the reader waiting for the rest of the thought. Common causes: a dependent clause alone, a phrase without a main verb, or a subject that never reaches its main verb."},{"t":"p","x":"A run-on / comma splice: joins two independent clauses without a suitable boundary. Repair it with a period, a semicolon, or a comma plus a coordinating conjunction."},{"t":"p","x":"A dependent-clause opener: needs a main clause: “Although the sample was small, the team repeated the test.” The clause beginning with although cannot stand alone."},{"t":"table","x":{"head":["Problem","Incorrect / incomplete","Possible repair"],"rows":[["Fragment","Although the evidence was limited.","Although the evidence was limited, the researchers repeated the study."],["Missing main verb","The students in the science club.","The students in the science club presented their findings."],["Comma splice","The trial ended, the team reviewed the data.","The trial ended; the team reviewed the data."],["Run-on","The survey was short it reached many residents.","The survey was short, but it reached many residents."]]}}]}],"practice":[{"g":"Sentences and Fragments","q":"Which option is a complete sentence?","c":["Because the library closed earlier than usual.","Although the results were promising, the team repeated the test.","While waiting for the final report.","After the students who joined the research club."],"a":1,"why":"B contains a dependent opening clause (“Although the results were promising”) and a complete main clause (“the team repeated the test”). The other options leave the reader waiting for a main clause.","ctx":[{"t":"p","x":"Choose the best answer, A–D. Questions 1–4 test sentence completeness and boundaries. Questions 5–12 test extended reasoning and analogy."}]},{"g":"Sentences and Fragments","q":"Choose the best revision of the fragment: “The students who volunteered at the community garden.”","c":["The students who volunteered at the community garden.","The students who volunteered at the community garden organized a seed exchange.","Because the students who volunteered at the community garden.","When the students who volunteered at the community garden."],"a":1,"why":"B completes the subject “The students who volunteered at the community garden” with the main verb “organized” and its object. A, C, and D remain incomplete."},{"g":"Sentences and Fragments","q":"Which choice correctly joins the two independent clauses? “The trial ended. The team reviewed the data.”","c":["The trial ended, the team reviewed the data.","The trial ended; the team reviewed the data.","The trial ended because, the team reviewed the data.","The trial ended the team, reviewed the data."],"a":1,"why":"A semicolon can join two closely related independent clauses. A creates a comma splice; C misuses because and punctuation; D is not grammatical."},{"g":"Sentences and Fragments","q":"Which option is a dependent-clause fragment when it appears alone?","c":["The experiment ended after the lights failed.","After the lights failed.","The lights failed, and the experiment ended.","The experiment ended; the lights failed."],"a":1,"why":"“After the lights failed” begins with the subordinating conjunction after and does not provide a main clause. The other options express complete thoughts."}]},"extended-reasoning":{"session":8,"kind":"Reading","title":"Extended Reasoning and Analysis","source":"Erica Meltzer, The Complete Guide to SAT Reading, p. 189","goal":"These questions ask you to carry a passage’s logic into a new situation. The answer may not repeat the passage’s words, but it must preserve the same rule or relationship.","sections":[{"h":"","blocks":[{"t":"ol","x":["Extract the rule What principle, cause-and-effect pattern, or decision rule does the passage establish?","State it generally Remove names and story details. For example: “The researcher rejects conclusions that rely on unverified evidence.”","Apply it to the new case Choose the option that follows the same rule in a different situation.","Check the strength Prefer what the passage supports. Avoid answers that claim “always,” “proves,” or “only” unless the evidence truly warrants them.","For analogies, compare relationships Match who does what, why, and with what result—not merely similar words or settings."]}]},{"h":"Common traps","blocks":[{"t":"ul","x":["Overgeneralization: turning “may” into “always” or one example into a universal rule.","Unsupported cause: assuming that because one event followed another, the first event caused it.","Superficial analogy: matching the setting or vocabulary while ignoring the relationship.","Outside knowledge: choosing what sounds true in real life instead of what the passage supports."]}]},{"h":"Connection to the official EST May 2026 paper","blocks":[{"t":"p","x":"The following are direct exam references. The full answer choices are not reproduced here; use the official May 2026 paper for the complete original items."},{"t":"ul","x":["Module 1, Q33 — Sentence-level grammar / punctuation. The item asks students to select the grammatically correct version of a sentence.","Module 2, Q8 and Q10 — Reasoning from geological evidence and understanding why an example supports a conclusion.","Module 2, Q19–Q20 — Evaluating the logic of evidence and relationships among ideas in an argument."]},{"t":"p","x":"Two short original stems from the exam:"},{"t":"ul","x":["Module 1, Q33: “Which option is the most grammatically correct?”","Module 2, Q19: “Which statement best evaluates the logic of the author's evidence regarding Pope's success?”"]},{"t":"p","x":"The 12 practice questions below are newly written for this handout. They are not official exam questions."}]}],"practice":[{"g":"Extended Reasoning and Analysis","q":"What would the botanist most reasonably recommend before making a broad claim about compost?","c":["Repeat the experiment with a larger sample while keeping other conditions consistent.","Conclude that compost makes every plant grow taller in every environment.","Stop collecting data because the first result proves the claim.","Change the type of seed in each pot to make the results more reliable."],"a":0,"why":"The small sample limits how confidently the class can generalize. A larger sample and consistent conditions test whether the pattern holds. B and C overstate the evidence; D adds a confounding variable.","ctx":[{"t":"p","x":"A botanist asked students to grow the same type of seed in identical pots. Half the pots received compost; the others did not. The compost group grew taller on average, but the class tested only six plants in each group."}]},{"g":"Extended Reasoning and Analysis","q":"Which conclusion is best supported by the information?","c":["The new bike lanes were the only cause of the increase.","Bike trips increased after installation, but the information does not isolate the lanes as the sole cause.","Protected bike lanes reduce bike use whenever the weather is mild.","Public transit expansion had no effect on travel choices."],"a":1,"why":"The passage reports a change after installation but also identifies other changes that could affect travel. It supports a cautious conclusion, not a claim of sole causation.","ctx":[{"t":"p","x":"After a city installed protected bike lanes, recorded bike trips rose by 18%. During the same months, the city also expanded public transit and experienced unusually mild weather."}]},{"g":"Extended Reasoning and Analysis","q":"Which situation follows the same principle?","c":["A coach selects a player because the player is the coach’s close friend.","A reviewer approves a report because its conclusion matches a popular opinion.","A reviewer accepts a carefully documented report even though its conclusion challenges the reviewer’s own view.","A manager rejects every report that contains an unexpected result."],"a":2,"why":"The underlying rule is to judge the quality of evidence rather than personal agreement. C preserves that relationship; the other options rely on bias or reject unexpected results automatically.","ctx":[{"t":"p","x":"A journal editor rejects a research claim when the evidence has not been checked, even if the claim agrees with the editor’s personal expectations. The editor accepts well-supported findings even when they challenge those expectations."}]},{"g":"Extended Reasoning and Analysis","q":"If an object is found in an undisturbed layer below a layer dated to 900 CE, what is the most reasonable inference?","c":["The object is likely older than the 900 CE layer.","The object must have been made in exactly 900 CE.","The object is certainly modern because it lies deeper.","The object proves that the site has never changed."],"a":0,"why":"The stated rule allows a relative-age inference: the lower layer formed earlier, so an object within it is likely older than the layer above. The evidence does not provide an exact date or prove the site never changed.","ctx":[{"t":"p","x":"An archaeologist dates objects by studying the layers in which they are found. At a site where the layers have not been disturbed, deeper layers generally formed before the layers above them."}]},{"g":"Extended Reasoning and Analysis","q":"What is the main limitation in the school’s reasoning if it claims tutoring caused the rise?","c":["The scores were measured at the end of the term.","The students attended a school.","Tutoring can never improve academic performance.","Without a comparison group, the school cannot rule out other explanations for the increase."],"a":3,"why":"A rise after tutoring does not, by itself, establish causation. A comparison group would help assess other explanations, such as regular instruction or changes in the test.","ctx":[{"t":"p","x":"A school introduced after-school tutoring. Students’ average scores rose at the end of the term. The school did not compare those students with a similar group that did not attend tutoring."}]},{"g":"Extended Reasoning and Analysis","q":"Which action best applies the researcher’s principle to a proposed free-transit program?","c":["Expand the program immediately because residents support it.","Reject the program because every public program has a cost.","Run a pilot, measure ridership and costs, and compare effects across neighborhoods before deciding.","Measure only the total number of buses, without studying who uses them."],"a":2,"why":"C applies all three parts of the principle: benefits, costs, and effects across neighborhoods. A relies only on support; B assumes the conclusion; D measures too little.","ctx":[{"t":"p","x":"A public-health researcher argues that a city should expand a program only after measuring its benefits, costs, and effects on different neighborhoods."}]},{"g":"Extended Reasoning and Analysis","q":"Which situation is most analogous?","c":["A teacher gives the highest mark to the student who stays latest, regardless of the work.","A project lead recognizes a team member who meets the agreed target accurately, even though the member worked fewer hours.","A supervisor rewards an employee for agreeing with every suggestion.","A team leader counts the number of meetings instead of checking completed work."],"a":1,"why":"The manager values results and accuracy rather than time spent. B follows the same rule; the other options reward time, agreement, or activity instead of outcomes.","ctx":[{"t":"p","x":"A manager evaluates employees by whether they complete agreed goals accurately, rather than by how many hours they remain at the office."}]},{"g":"Extended Reasoning and Analysis","q":"Which conclusion best follows from the passage?","c":["Peer review can improve reliability, but readers should not treat it as proof that a study is error-free.","Peer review makes every published study correct.","Reviewers should reject every study that challenges their assumptions.","Peer review has no value because reviewers can make mistakes."],"a":0,"why":"The passage presents peer review as useful but limited. A preserves both parts. B overstates its power; C contradicts the purpose of fair review; D ignores its benefits.","ctx":[{"t":"p","x":"Peer review can reveal mistakes because other specialists examine a study before publication. Reviewers can still share assumptions or overlook weaknesses, so review is one safeguard rather than a guarantee."}]}]},"drills-8":{"session":8,"kind":"Practice","title":"Mixed Review: Practice Test 2","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 8, mixed together like the real exam.","sections":[],"practice":[{"g":"Practice Test 2: Mixed Practice","q":"Which option is a complete sentence?","c":["Because the library closed earlier than usual.","Although the results were promising, the team repeated the test.","While waiting for the final report.","After the students who joined the research club."],"a":1,"why":"B contains a dependent opening clause (“Although the results were promising”) and a complete main clause (“the team repeated the test”). The other options leave the reader waiting for a main clause.","ctx":[{"t":"p","x":"Choose the best answer, A–D. Questions 1–4 test sentence completeness and boundaries. Questions 5–12 test extended reasoning and analogy."}]},{"g":"Practice Test 2: Mixed Practice","q":"Choose the best revision of the fragment: “The students who volunteered at the community garden.”","c":["The students who volunteered at the community garden.","The students who volunteered at the community garden organized a seed exchange.","Because the students who volunteered at the community garden.","When the students who volunteered at the community garden."],"a":1,"why":"B completes the subject “The students who volunteered at the community garden” with the main verb “organized” and its object. A, C, and D remain incomplete."},{"g":"Practice Test 2: Mixed Practice","q":"Which choice correctly joins the two independent clauses? “The trial ended. The team reviewed the data.”","c":["The trial ended, the team reviewed the data.","The trial ended; the team reviewed the data.","The trial ended because, the team reviewed the data.","The trial ended the team, reviewed the data."],"a":1,"why":"A semicolon can join two closely related independent clauses. A creates a comma splice; C misuses because and punctuation; D is not grammatical."},{"g":"Practice Test 2: Mixed Practice","q":"Which option is a dependent-clause fragment when it appears alone?","c":["The experiment ended after the lights failed.","After the lights failed.","The lights failed, and the experiment ended.","The experiment ended; the lights failed."],"a":1,"why":"“After the lights failed” begins with the subordinating conjunction after and does not provide a main clause. The other options express complete thoughts."},{"g":"Practice Test 2: Mixed Practice","q":"What would the botanist most reasonably recommend before making a broad claim about compost?","c":["Repeat the experiment with a larger sample while keeping other conditions consistent.","Conclude that compost makes every plant grow taller in every environment.","Stop collecting data because the first result proves the claim.","Change the type of seed in each pot to make the results more reliable."],"a":0,"why":"The small sample limits how confidently the class can generalize. A larger sample and consistent conditions test whether the pattern holds. B and C overstate the evidence; D adds a confounding variable.","ctx":[{"t":"p","x":"A botanist asked students to grow the same type of seed in identical pots. Half the pots received compost; the others did not. The compost group grew taller on average, but the class tested only six plants in each group."}]},{"g":"Practice Test 2: Mixed Practice","q":"Which conclusion is best supported by the information?","c":["The new bike lanes were the only cause of the increase.","Bike trips increased after installation, but the information does not isolate the lanes as the sole cause.","Protected bike lanes reduce bike use whenever the weather is mild.","Public transit expansion had no effect on travel choices."],"a":1,"why":"The passage reports a change after installation but also identifies other changes that could affect travel. It supports a cautious conclusion, not a claim of sole causation.","ctx":[{"t":"p","x":"After a city installed protected bike lanes, recorded bike trips rose by 18%. During the same months, the city also expanded public transit and experienced unusually mild weather."}]},{"g":"Practice Test 2: Mixed Practice","q":"Which situation follows the same principle?","c":["A coach selects a player because the player is the coach’s close friend.","A reviewer approves a report because its conclusion matches a popular opinion.","A reviewer accepts a carefully documented report even though its conclusion challenges the reviewer’s own view.","A manager rejects every report that contains an unexpected result."],"a":2,"why":"The underlying rule is to judge the quality of evidence rather than personal agreement. C preserves that relationship; the other options rely on bias or reject unexpected results automatically.","ctx":[{"t":"p","x":"A journal editor rejects a research claim when the evidence has not been checked, even if the claim agrees with the editor’s personal expectations. The editor accepts well-supported findings even when they challenge those expectations."}]},{"g":"Practice Test 2: Mixed Practice","q":"If an object is found in an undisturbed layer below a layer dated to 900 CE, what is the most reasonable inference?","c":["The object is likely older than the 900 CE layer.","The object must have been made in exactly 900 CE.","The object is certainly modern because it lies deeper.","The object proves that the site has never changed."],"a":0,"why":"The stated rule allows a relative-age inference: the lower layer formed earlier, so an object within it is likely older than the layer above. The evidence does not provide an exact date or prove the site never changed.","ctx":[{"t":"p","x":"An archaeologist dates objects by studying the layers in which they are found. At a site where the layers have not been disturbed, deeper layers generally formed before the layers above them."}]},{"g":"Practice Test 2: Mixed Practice","q":"What is the main limitation in the school’s reasoning if it claims tutoring caused the rise?","c":["The scores were measured at the end of the term.","The students attended a school.","Tutoring can never improve academic performance.","Without a comparison group, the school cannot rule out other explanations for the increase."],"a":3,"why":"A rise after tutoring does not, by itself, establish causation. A comparison group would help assess other explanations, such as regular instruction or changes in the test.","ctx":[{"t":"p","x":"A school introduced after-school tutoring. Students’ average scores rose at the end of the term. The school did not compare those students with a similar group that did not attend tutoring."}]},{"g":"Practice Test 2: Mixed Practice","q":"Which action best applies the researcher’s principle to a proposed free-transit program?","c":["Expand the program immediately because residents support it.","Reject the program because every public program has a cost.","Run a pilot, measure ridership and costs, and compare effects across neighborhoods before deciding.","Measure only the total number of buses, without studying who uses them."],"a":2,"why":"C applies all three parts of the principle: benefits, costs, and effects across neighborhoods. A relies only on support; B assumes the conclusion; D measures too little.","ctx":[{"t":"p","x":"A public-health researcher argues that a city should expand a program only after measuring its benefits, costs, and effects on different neighborhoods."}]},{"g":"Practice Test 2: Mixed Practice","q":"Which situation is most analogous?","c":["A teacher gives the highest mark to the student who stays latest, regardless of the work.","A project lead recognizes a team member who meets the agreed target accurately, even though the member worked fewer hours.","A supervisor rewards an employee for agreeing with every suggestion.","A team leader counts the number of meetings instead of checking completed work."],"a":1,"why":"The manager values results and accuracy rather than time spent. B follows the same rule; the other options reward time, agreement, or activity instead of outcomes.","ctx":[{"t":"p","x":"A manager evaluates employees by whether they complete agreed goals accurately, rather than by how many hours they remain at the office."}]},{"g":"Practice Test 2: Mixed Practice","q":"Which conclusion best follows from the passage?","c":["Peer review can improve reliability, but readers should not treat it as proof that a study is error-free.","Peer review makes every published study correct.","Reviewers should reject every study that challenges their assumptions.","Peer review has no value because reviewers can make mistakes."],"a":0,"why":"The passage presents peer review as useful but limited. A preserves both parts. B overstates its power; C contradicts the purpose of fair review; D ignores its benefits.","ctx":[{"t":"p","x":"Peer review can reveal mistakes because other specialists examine a study before publication. Reviewers can still share assumptions or overlook weaknesses, so review is one safeguard rather than a guarantee."}]}]},"combining-separating":{"session":9,"kind":"Grammar","title":"Combining & Separating Sentences","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 85","goal":"Start by identifying the clauses. An independent clause can stand alone; a dependent clause cannot. Then choose a boundary that fits both the grammar and the relationship between the ideas.","sections":[{"h":"Learning targets","blocks":[{"t":"ul","x":["Join related independent clauses without creating a comma splice or run-on.","Choose punctuation that matches the grammatical structure and relationship between ideas.","Explain why an author includes a phrase, sentence, example, quotation, or piece of evidence.","Distinguish a detail’s topic from its function in the argument or passage."]}]},{"h":"","blocks":[{"t":"p","x":"Use a period: to separate two complete thoughts when you want a clear stop."},{"t":"p","x":"Use a semicolon: between two closely related independent clauses: each side must be able to stand as a sentence."},{"t":"p","x":"Use comma + FANBOYS: to join independent clauses when the relationship is addition, contrast, choice, reason/result, or similar. FANBOYS = for, and, nor, but, or, yet, so."},{"t":"p","x":"Use a subordinating conjunction: when one idea depends on the other: Because the road flooded, the team postponed the survey."},{"t":"p","x":"Use a colon: after a complete independent clause to introduce an explanation, example, list, or result."},{"t":"p","x":"Use a dash: to create a strong break or add an emphatic explanation; do not use it to disguise a fragment."},{"t":"table","x":{"head":["Error","Incorrect","Repair"],"rows":[["Comma splice","The data were incomplete, the team repeated the study.","The data were incomplete, so the team repeated the study. / The data were incomplete; the team repeated the study."],["Run-on","The data were incomplete the team repeated the study.","The data were incomplete. The team repeated the study."],["Wrong semicolon","Because the road flooded; the team postponed the survey.","Because the road flooded, the team postponed the survey."],["Colon after a fragment","The reason was: the road flooded.","The reason was clear: the road flooded."]]}}]},{"h":"Fast decision routine","blocks":[{"t":"ol","x":["Underline the subject and finite verb in each clause.","Mark each clause I (independent) or D (dependent).","If two I clauses meet, use a period, semicolon, or comma + FANBOYS; do not use only a comma.","If a clause begins with because, although, when, if, while, or another subordinating word, attach it to a main clause.","Read the sentence aloud once to check that the punctuation matches the intended meaning."]}]}],"practice":[{"g":"Combining & Separating Sentences","q":"Which revision correctly joins the two independent clauses? “The sample was small. The researchers reported the limitation.”","c":["The sample was small, the researchers reported the limitation.","The sample was small; the researchers reported the limitation.","The sample was small; because the researchers reported the limitation.","The sample was small, the researchers reported; the limitation."],"a":1,"why":"A semicolon joins two complete, closely related independent clauses. A creates a comma splice; C and D are structurally incomplete or incorrectly punctuated.","ctx":[{"t":"p","x":"Choose the best answer, A–D. Questions 1–6 focus on sentence boundaries. Questions 7–12 focus on authorial function."}]},{"g":"Combining & Separating Sentences","q":"Choose the best revision: “The road was flooded, the delivery arrived late.”","c":["The road was flooded, so the delivery arrived late.","The road was flooded; so the delivery arrived late.","The road was flooded because, the delivery arrived late.","The road was flooded the delivery, arrived late."],"a":0,"why":"A comma plus the coordinating conjunction “so” correctly joins the clauses and expresses a cause-and- result relationship."},{"g":"Combining & Separating Sentences","q":"Which sentence uses a colon correctly?","c":["The committee had one priority: to protect the historic building.","The committee decided: to protect the historic building was important.","The committee: had one priority to protect the historic building.","The committee had: one priority to protect the historic building."],"a":0,"why":"The clause before the colon is complete. The colon introduces an explanation of the priority."},{"g":"Combining & Separating Sentences","q":"Which option best separates two ideas that should stand as separate sentences?","c":["The museum reopened, visitors returned in large numbers.","The museum reopened; and visitors returned in large numbers.","The museum reopened. Visitors returned in large numbers.","The museum reopened, because. Visitors returned in large numbers."],"a":2,"why":"Both clauses can stand independently, and a period cleanly separates the complete thoughts. B misuses the semicolon with “and”; A is a comma splice."},{"g":"Combining & Separating Sentences","q":"Which revision best expresses a contrast without creating a run-on?","c":["The first test was brief, the second test took nearly an hour.","The first test was brief, but the second test took nearly an hour.","The first test was brief; but the second test took nearly an hour.","Although the first test was brief. The second test took nearly an hour."],"a":1,"why":"The comma plus “but” joins two independent clauses and clearly signals contrast."},{"g":"Combining & Separating Sentences","q":"Which option is a complete and correctly punctuated sentence?","c":["Because the equipment failed; the team stopped the trial.","The equipment failed, the team stopped the trial.","The equipment failed; therefore, the team stopped the trial.","The equipment failed; therefore the team, stopped the trial."],"a":2,"why":"A semicolon can precede a conjunctive adverb such as “therefore,” followed by a comma. Both sides contain independent clauses."}]},"function-questions":{"session":9,"kind":"Reading","title":"Function Questions","source":"Erica Meltzer, The Complete Guide to SAT Reading, p. 204","goal":"A function question asks what a part of a passage DOES—not just what it says. Typical wording includes “Why does the author mention…?”, “What is the purpose of…?”, “How does this example support the claim?”, and “What role does this sentence play?”","sections":[{"h":"","blocks":[{"t":"ol","x":["Name the target Is the question asking about a word, phrase, sentence, example, quotation, paragraph, or graphic?","Read around it Read the target plus the sentence before and after it. Function depends on context.","State the job Complete this sentence in your own words: “The author includes this detail in order to…”","Connect to the main point Ask how the detail develops, supports, qualifies, illustrates, contrasts with, or transitions from the main idea.","Reject topic-only answers An option may describe what a detail says without explaining why the author included it."]}]},{"h":"Common functions","blocks":[{"t":"table","x":{"head":["Function","What it does"],"rows":[["Illustrate","give a concrete example of a general claim"],["Support","provide evidence for a claim"],["Qualify / limit","show that a claim is not universal or absolute"],["Contrast","highlight a difference between ideas or cases"],["Explain a process","show how or why something happens"],["Shift / transition","move the discussion from one idea to the next"],["Provide context","give background needed to understand a claim"]]}}]}],"practice":[{"g":"Function Questions","q":"What is the primary function of the comparison between the two blocks? A city planner argues that trees can reduce street temperatures. To make the claim concrete, she compares two nearby blocks: one shaded by mature trees and one with little shade. The shaded block records lower afternoon temperatures.","c":["To introduce an unrelated problem with city planning","To provide a concrete example that supports the claim about shade and temperature","To prove that trees are the only factor that affects street temperature","To shift the passage from urban planning to the history of forests"],"a":1,"why":"The comparison supplies a specific example that supports the general claim. It does not prove that trees are the only factor."},{"g":"Function Questions","q":"Why does the author mention the second survey? The first survey found that most residents supported the new bus route. A second survey, conducted in neighborhoods farther from the route, found weaker support. The difference suggests that access may shape public opinion.","c":["To show that the first survey was conducted illegally","To repeat the first survey’s result without adding information","To qualify the initial finding by showing that support varied by neighborhood","To prove that residents oppose all public transportation"],"a":2,"why":"The second survey complicates the broad initial finding by showing variation across locations. That is a qualifying function."},{"g":"Function Questions","q":"What role does the tracking-device evidence play in the passage? For decades, researchers assumed that the bird migrated only at night. A tracking device later recorded several daytime flights. The team therefore revised its model of the bird’s migration.","c":["It provides evidence that challenges the earlier assumption.","It explains why tracking devices were invented.","It supports the claim that the bird never migrates at night.","It introduces a topic unrelated to migration."],"a":0,"why":"The daytime flights conflict with the absolute earlier assumption and prompt a revised model."},{"g":"Function Questions","q":"Why does the author discuss the failed design? The author describes a failed bridge design before explaining the successful redesign. The failure revealed that the original supports could not withstand strong crosswinds.","c":["To ridicule the engineers who worked on the bridge","To provide background and explain the problem that the redesign had to solve","To argue that every bridge design must fail before it succeeds","To change the subject from engineering to weather forecasting"],"a":1,"why":"The failure establishes the problem and helps explain the purpose of the later redesign."},{"g":"Function Questions","q":"What is the function of the second sentence? The article first describes how wetlands absorb excess rainwater. It then notes that wetlands also provide habitats for fish, insects, and migratory birds.","c":["To contradict the claim that wetlands absorb water","To provide an additional benefit, broadening the discussion of wetlands’ value","To explain how fish create heavy rainfall","To conclude that wetlands have no ecological importance"],"a":1,"why":"The second sentence adds another benefit rather than contradicting or replacing the first point."},{"g":"Function Questions","q":"What is the function of the warning about participation? The report praises the program’s high participation rate but warns that participation alone does not show whether students learned more. It recommends comparing learning outcomes before and after the program.","c":["To dismiss all numerical evidence as useless","To qualify the positive assessment and identify what further evidence is needed","To claim that student learning cannot be measured","To introduce a new topic unrelated to the program"],"a":1,"why":"The warning limits what can be concluded from participation data and motivates the recommendation to measure outcomes."}]},"drills-9":{"session":9,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 9, mixed together like the real exam.","sections":[],"practice":[{"g":"Drill Exercises","q":"Which revision correctly joins the two independent clauses? “The sample was small. The researchers reported the limitation.”","c":["The sample was small, the researchers reported the limitation.","The sample was small; the researchers reported the limitation.","The sample was small; because the researchers reported the limitation.","The sample was small, the researchers reported; the limitation."],"a":1,"why":"A semicolon joins two complete, closely related independent clauses. A creates a comma splice; C and D are structurally incomplete or incorrectly punctuated.","ctx":[{"t":"p","x":"Choose the best answer, A–D. Questions 1–6 focus on sentence boundaries. Questions 7–12 focus on authorial function."}]},{"g":"Drill Exercises","q":"Choose the best revision: “The road was flooded, the delivery arrived late.”","c":["The road was flooded, so the delivery arrived late.","The road was flooded; so the delivery arrived late.","The road was flooded because, the delivery arrived late.","The road was flooded the delivery, arrived late."],"a":0,"why":"A comma plus the coordinating conjunction “so” correctly joins the clauses and expresses a cause-and- result relationship."},{"g":"Drill Exercises","q":"Which sentence uses a colon correctly?","c":["The committee had one priority: to protect the historic building.","The committee decided: to protect the historic building was important.","The committee: had one priority to protect the historic building.","The committee had: one priority to protect the historic building."],"a":0,"why":"The clause before the colon is complete. The colon introduces an explanation of the priority."},{"g":"Drill Exercises","q":"Which option best separates two ideas that should stand as separate sentences?","c":["The museum reopened, visitors returned in large numbers.","The museum reopened; and visitors returned in large numbers.","The museum reopened. Visitors returned in large numbers.","The museum reopened, because. Visitors returned in large numbers."],"a":2,"why":"Both clauses can stand independently, and a period cleanly separates the complete thoughts. B misuses the semicolon with “and”; A is a comma splice."},{"g":"Drill Exercises","q":"Which revision best expresses a contrast without creating a run-on?","c":["The first test was brief, the second test took nearly an hour.","The first test was brief, but the second test took nearly an hour.","The first test was brief; but the second test took nearly an hour.","Although the first test was brief. The second test took nearly an hour."],"a":1,"why":"The comma plus “but” joins two independent clauses and clearly signals contrast."},{"g":"Drill Exercises","q":"Which option is a complete and correctly punctuated sentence?","c":["Because the equipment failed; the team stopped the trial.","The equipment failed, the team stopped the trial.","The equipment failed; therefore, the team stopped the trial.","The equipment failed; therefore the team, stopped the trial."],"a":2,"why":"A semicolon can precede a conjunctive adverb such as “therefore,” followed by a comma. Both sides contain independent clauses."},{"g":"Drill Exercises","q":"What is the primary function of the comparison between the two blocks? A city planner argues that trees can reduce street temperatures. To make the claim concrete, she compares two nearby blocks: one shaded by mature trees and one with little shade. The shaded block records lower afternoon temperatures.","c":["To introduce an unrelated problem with city planning","To provide a concrete example that supports the claim about shade and temperature","To prove that trees are the only factor that affects street temperature","To shift the passage from urban planning to the history of forests"],"a":1,"why":"The comparison supplies a specific example that supports the general claim. It does not prove that trees are the only factor."},{"g":"Drill Exercises","q":"Why does the author mention the second survey? The first survey found that most residents supported the new bus route. A second survey, conducted in neighborhoods farther from the route, found weaker support. The difference suggests that access may shape public opinion.","c":["To show that the first survey was conducted illegally","To repeat the first survey’s result without adding information","To qualify the initial finding by showing that support varied by neighborhood","To prove that residents oppose all public transportation"],"a":2,"why":"The second survey complicates the broad initial finding by showing variation across locations. That is a qualifying function."},{"g":"Drill Exercises","q":"What role does the tracking-device evidence play in the passage? For decades, researchers assumed that the bird migrated only at night. A tracking device later recorded several daytime flights. The team therefore revised its model of the bird’s migration.","c":["It provides evidence that challenges the earlier assumption.","It explains why tracking devices were invented.","It supports the claim that the bird never migrates at night.","It introduces a topic unrelated to migration."],"a":0,"why":"The daytime flights conflict with the absolute earlier assumption and prompt a revised model."},{"g":"Drill Exercises","q":"Why does the author discuss the failed design? The author describes a failed bridge design before explaining the successful redesign. The failure revealed that the original supports could not withstand strong crosswinds.","c":["To ridicule the engineers who worked on the bridge","To provide background and explain the problem that the redesign had to solve","To argue that every bridge design must fail before it succeeds","To change the subject from engineering to weather forecasting"],"a":1,"why":"The failure establishes the problem and helps explain the purpose of the later redesign."},{"g":"Drill Exercises","q":"What is the function of the second sentence? The article first describes how wetlands absorb excess rainwater. It then notes that wetlands also provide habitats for fish, insects, and migratory birds.","c":["To contradict the claim that wetlands absorb water","To provide an additional benefit, broadening the discussion of wetlands’ value","To explain how fish create heavy rainfall","To conclude that wetlands have no ecological importance"],"a":1,"why":"The second sentence adds another benefit rather than contradicting or replacing the first point."},{"g":"Drill Exercises","q":"What is the function of the warning about participation? The report praises the program’s high participation rate but warns that participation alone does not show whether students learned more. It recommends comparing learning outcomes before and after the program.","c":["To dismiss all numerical evidence as useless","To qualify the positive assessment and identify what further evidence is needed","To claim that student learning cannot be measured","To introduce a new topic unrelated to the program"],"a":1,"why":"The warning limits what can be concluded from participation data and motivates the recommendation to measure outcomes."}]},"cumulative-review-1":{"session":10,"kind":"Grammar","title":"Cumulative Review","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar","goal":"Use this set diagnostically. After marking an answer, name the skill that made the question difficult.","sections":[{"h":"","blocks":[{"t":"ul","x":["Language and editing: parts of speech, vocabulary in context, diction/register, relevance, concision, sentence boundaries.","Reading: literal meaning, paraphrase, sentence order, supporting evidence, reasonable inference.","Reasoning: concrete-to-abstract thinking, extended reasoning, authorial function, cause versus correlation.","Tone and attitude: word choice, qualifiers, strength of claims, positive/negative/mixed/neutral stance."]}]}],"practice":[{"g":"Vocabulary in context","q":"In “The results were consistent with earlier findings,” consistent most nearly means:","c":["In conflict with","In agreement with","Unrelated to","More expensive than"],"a":1,"why":"The phrase “with earlier findings” signals agreement.","ctx":[{"t":"p","x":"Choose the best answer, A–D."}]},{"g":"Parts of speech","q":"“The committee reached a ______ decision after reviewing the evidence.”","c":["carefully","care","careful","caring for"],"a":2,"why":"An adjective modifies the noun “decision.”"},{"g":"Relevance and revision","q":"A paragraph argues that school gardens support science learning. Which sentence is least relevant?","c":["Students observe plant growth over several weeks.","Recording measurements gives students data to compare.","Some students prefer blue notebooks to green notebooks.","Comparing results raises questions about light and water."],"a":2,"why":"Notebook colour does not support the paragraph’s claim."},{"g":"Concrete to abstract","q":"A student sees three plants bend toward a window. Which conclusion is best supported?","c":["Every plant always bends toward every window.","Some plants may grow toward a source of light.","Windows stop all plants from growing.","Plants grow only indoors."],"a":1,"why":"B generalizes cautiously from the observations."},{"g":"Sentence order","q":"Arrange the steps: (1) Finally, compare results. (2) Select two similar plots. (3) Record growth weekly. (4) Give compost to one plot only.","c":["2–4–3–1","1–2–3–4","4–1–2–3","3–2–1–4"],"a":0,"why":"Select plots, apply the treatment, record growth, then compare."},{"g":"Supporting evidence","q":"Claim: “New library hours helped working students.” Which evidence best supports it?","c":["The library has blue signs.","Working students report that they can visit after their shifts.","The building is twenty years old.","The librarian enjoys historical novels."],"a":1,"why":"This directly links the new hours to working students’ access."},{"g":"Concision","q":"Choose the clearest revision: “Due to the fact that the road was icy, the bus arrived late.”","c":["In light of the fact that the road was icy, the bus arrived late.","Because the road was icy, the bus arrived late.","The bus, due to icy road conditions, arrived late in time.","The road was icy in nature, and this was the reason why the bus arrived late."],"a":1,"why":"B preserves the meaning with fewer words."},{"g":"Literal comprehension","q":"“The museum closes at 6 p.m. on weekdays, but visitors may enter until 5:30 p.m.” Which statement matches?","c":["Visitors may enter at 5:45 p.m.","The museum closes at 5:30 p.m.","Weekday entry ends half an hour before closing.","The museum opens only on weekdays."],"a":2,"why":"Entry ends thirty minutes before closing."},{"g":"Diction and register","q":"“The researchers ______ the samples under controlled conditions.” Which verb best fits a formal report?","c":["checked out","looked at some stuff","examined","messed with"],"a":2,"why":"“Examined” is precise and formal."},{"g":"Reasonable inference","q":"Mina brings an umbrella, checks a weather alert, and moves outdoor books inside before the afternoon. What is the best inference?","c":["Mina expects poor weather.","Mina plans to sell the books.","The books were damaged by fire.","Mina dislikes reading outdoors in every season."],"a":0,"why":"The actions suggest that Mina anticipates poor weather."},{"g":"Sentence boundaries","q":"Which option is a complete sentence?","c":["Although the first sample was contaminated.","When the researchers finished collecting data.","The researchers repeated the test after cleaning the equipment.","Because the equipment had not been cleaned."],"a":2,"why":"C contains an independent clause; the others are dependent-clause fragments."},{"g":"Extended reasoning and tone","q":"A report says: “The early measurements are encouraging, but the sample is too small to support a firm conclusion.” Which label best describes the writer’s attitude?","c":["Cautiously optimistic","Furious","Mocking","Completely certain"],"a":0,"why":"“Encouraging” is positive, while the limitation signals caution."}]},"tone-attitude":{"session":10,"kind":"Reading","title":"Tone and Attitude","source":"Erica Meltzer, The Complete Guide to SAT Reading, p. 232","goal":"Tone is the quality or manner of the writing: informative, skeptical, appreciative, urgent, humorous. Attitude is the author’s position or feeling toward the subject: approval, doubt, concern, admiration, disapproval.","sections":[{"h":"Four-step method","blocks":[{"t":"ul","x":["Find evidence words: underline adjectives, verbs, qualifiers, and contrast markers.","Choose the direction: positive, negative, mixed, or neutral/informative.","Choose the right strength: “cautiously optimistic” may fit better than “thrilled”; “skeptical” may fit better than “furious.”","Test the label against the whole passage. One positive word does not make a passage enthusiastic if the writer limits the claim."]}]},{"h":"Tone ladder","blocks":[{"t":"ul","x":["Measured / neutral: informative, descriptive, analytical.","Mildly positive: appreciative, approving, cautiously optimistic.","Mildly negative: skeptical, doubtful, critical, concerned.","Extreme: furious, outraged, ecstatic, contemptuous — choose these only when the language strongly supports them."]}]},{"h":"EST 2026 alignment","blocks":[{"t":"p","x":"The 2026 EST HS Literacy design integrates Writing (Module 1), Reading (Module 2), and Reading and Writing (Module 3). Tone and attitude most directly connect to interpreting a passage’s point of view and language, while cumulative review also checks editing and reasoning skills. The next two items reproduce the wording and answer choices of relevant questions from the supplied May 2026 EST paper. All 12 questions in Part 4 are newly written."}]}],"practice":[{"g":"Tone and attitude","q":"“The council’s response to the flood was, at best, slow and, at worst, careless.” What is the author’s tone?","c":["admiring","critical","neutral","playful"],"a":1,"why":"“Slow” and “careless” are negative judgements, so the tone is critical."},{"g":"Tone and attitude","q":"“Although early trials are encouraging, researchers caution that larger studies are needed.” The tone is best described as","c":["cautiously optimistic","hostile","indifferent","boastful"],"a":0,"why":"Encouraging (positive) plus caution (limit) = cautiously optimistic."},{"g":"Tone and attitude","q":"“It is difficult to overstate the brilliance of her design; every detail serves a purpose.” The author’s attitude toward the design is","c":["skeptical","admiring","confused","detached"],"a":1,"why":"“Difficult to overstate the brilliance” is strong praise."},{"g":"Tone and attitude","q":"“The report lists the dates, locations and attendance figures without comment.” The tone of the report is","c":["emotional","objective","mocking","urgent"],"a":1,"why":"Facts without opinion signal an objective, neutral tone."},{"g":"Tone and attitude","q":"“Surely no reasonable person could believe that one small survey settles the matter.” The author is","c":["doubtful of the survey’s value","delighted by the survey","neutral about the survey","confused by the survey"],"a":0,"why":"“Surely no reasonable person” signals doubt about the survey’s weight."}]},"drills-10":{"session":10,"kind":"Practice","title":"Cumulative Practice","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 10, mixed together like the real exam.","sections":[],"practice":[{"g":"Vocabulary in context","q":"In “The results were consistent with earlier findings,” consistent most nearly means:","c":["In conflict with","In agreement with","Unrelated to","More expensive than"],"a":1,"why":"The phrase “with earlier findings” signals agreement.","ctx":[{"t":"p","x":"Choose the best answer, A–D."}]},{"g":"Parts of speech","q":"“The committee reached a ______ decision after reviewing the evidence.”","c":["carefully","care","careful","caring for"],"a":2,"why":"An adjective modifies the noun “decision.”"},{"g":"Relevance and revision","q":"A paragraph argues that school gardens support science learning. Which sentence is least relevant?","c":["Students observe plant growth over several weeks.","Recording measurements gives students data to compare.","Some students prefer blue notebooks to green notebooks.","Comparing results raises questions about light and water."],"a":2,"why":"Notebook colour does not support the paragraph’s claim."},{"g":"Concrete to abstract","q":"A student sees three plants bend toward a window. Which conclusion is best supported?","c":["Every plant always bends toward every window.","Some plants may grow toward a source of light.","Windows stop all plants from growing.","Plants grow only indoors."],"a":1,"why":"B generalizes cautiously from the observations."},{"g":"Sentence order","q":"Arrange the steps: (1) Finally, compare results. (2) Select two similar plots. (3) Record growth weekly. (4) Give compost to one plot only.","c":["2–4–3–1","1–2–3–4","4–1–2–3","3–2–1–4"],"a":0,"why":"Select plots, apply the treatment, record growth, then compare."},{"g":"Supporting evidence","q":"Claim: “New library hours helped working students.” Which evidence best supports it?","c":["The library has blue signs.","Working students report that they can visit after their shifts.","The building is twenty years old.","The librarian enjoys historical novels."],"a":1,"why":"This directly links the new hours to working students’ access."},{"g":"Concision","q":"Choose the clearest revision: “Due to the fact that the road was icy, the bus arrived late.”","c":["In light of the fact that the road was icy, the bus arrived late.","Because the road was icy, the bus arrived late.","The bus, due to icy road conditions, arrived late in time.","The road was icy in nature, and this was the reason why the bus arrived late."],"a":1,"why":"B preserves the meaning with fewer words."},{"g":"Literal comprehension","q":"“The museum closes at 6 p.m. on weekdays, but visitors may enter until 5:30 p.m.” Which statement matches?","c":["Visitors may enter at 5:45 p.m.","The museum closes at 5:30 p.m.","Weekday entry ends half an hour before closing.","The museum opens only on weekdays."],"a":2,"why":"Entry ends thirty minutes before closing."},{"g":"Diction and register","q":"“The researchers ______ the samples under controlled conditions.” Which verb best fits a formal report?","c":["checked out","looked at some stuff","examined","messed with"],"a":2,"why":"“Examined” is precise and formal."},{"g":"Reasonable inference","q":"Mina brings an umbrella, checks a weather alert, and moves outdoor books inside before the afternoon. What is the best inference?","c":["Mina expects poor weather.","Mina plans to sell the books.","The books were damaged by fire.","Mina dislikes reading outdoors in every season."],"a":0,"why":"The actions suggest that Mina anticipates poor weather."},{"g":"Sentence boundaries","q":"Which option is a complete sentence?","c":["Although the first sample was contaminated.","When the researchers finished collecting data.","The researchers repeated the test after cleaning the equipment.","Because the equipment had not been cleaned."],"a":2,"why":"C contains an independent clause; the others are dependent-clause fragments."},{"g":"Extended reasoning and tone","q":"A report says: “The early measurements are encouraging, but the sample is too small to support a firm conclusion.” Which label best describes the writer’s attitude?","c":["Cautiously optimistic","Furious","Mocking","Completely certain"],"a":0,"why":"“Encouraging” is positive, while the limitation signals caution."}]},"transitions":{"session":11,"kind":"Grammar","title":"Transitions","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 95","goal":"A transition is a signpost: it tells the reader how the next idea relates to the previous one. Name the relationship first; then choose the transition that expresses it.","sections":[{"h":"Learning targets","blocks":[{"t":"ul","x":["Choose transitions by identifying the logical relationship between ideas.","Punctuate transitions correctly when they connect independent clauses.","Explain how an example, quotation, paragraph, point of view, or counterargument advances an author's purpose.","Distinguish a detail's content from the rhetorical job it performs."]}]},{"h":"","blocks":[{"t":"table","x":{"head":["Relationship","Common transitions","What it signals"],"rows":[["Addition","also, furthermore, moreover, in addition","A second supporting point"],["Contrast","however, nevertheless, by contrast, on the other hand","The next idea differs from or limits the previous one"],["Cause / result","therefore, consequently, as a result, thus","One idea leads to another"],["Example","for example, for instance","A specific case illustrates a general claim"],["Sequence","first, next, subsequently, finally","Events or steps follow an order"],["Concession","admittedly, even so, nevertheless","A point is accepted, but the main argument continues"],["Restatement / emphasis","in fact, indeed, specifically","Clarification, emphasis, or a more precise point"],["Conclusion","overall, in sum, ultimately","A final synthesis or judgment"]]}}]},{"h":"Four-step transition method","blocks":[{"t":"ol","x":["Read both sides of the blank; the relationship matters more than the isolated sentence.","Name the relationship: addition, contrast, cause/result, example, sequence, concession, or conclusion.","Predict a transition before checking the options.","Insert it and reread the full passage for meaning, grammar, and punctuation."]}]},{"h":"Punctuation that often decides the answer","blocks":[{"t":"table","x":{"head":["Type","Model","Rule"],"rows":[["Conjunctive adverb","The trial failed; therefore, the team revised the method.","Use a semicolon or period before therefore/however/moreover when joining complete clauses; place a comma after the transition."],["Coordinating conjunction","The trial failed, so the team revised the method.","Use comma + and/but/so/yet/for/or/nor between independent clauses."],["Subordinating conjunction","Although the trial failed, the team learned from it.","Although/because/whereas introduce a dependent clause; attach it to a main clause."]]}}]}],"practice":[{"g":"Transitions","q":"The new filter removed most large particles. ______, it did not eliminate dissolved salts.","c":["Therefore","However","For example","Similarly"],"a":1,"why":"The second sentence limits the success described in the first, so a contrast transition fits.","ctx":[{"t":"p","x":"Choose the best answer, A–D. Questions 1–6 focus on transitions; Questions 7–12 focus on rhetorical strategy."}]},{"g":"Transitions","q":"The first trial produced inconsistent readings; ______, the researchers calibrated the sensor before repeating it.","c":["consequently","nevertheless","similarly","for instance"],"a":0,"why":"The inconsistent readings prompted the calibration. “Consequently” signals the result; the semicolon and following comma are correct."},{"g":"Transitions","q":"Some birds migrate thousands of kilometers. ______, the Arctic tern travels between polar regions each year.","c":["In contrast","For instance","Nevertheless","Consequently"],"a":1,"why":"The second sentence gives a specific example of the general statement."},{"g":"Transitions","q":"The museum extended its opening hours; ______, attendance among working adults increased.","c":["as a result","on the other hand","for example","meanwhile"],"a":0,"why":"The second clause describes an outcome. Use a semicolon before the conjunctive transition and a comma after it."},{"g":"Transitions","q":"Which sentence uses however correctly?","c":["The forecast looked clear, however, the team postponed the launch.","The forecast looked clear; however, the team postponed the launch.","The forecast looked clear however; the team postponed the launch.","The forecast looked clear; however the team, postponed the launch."],"a":1,"why":"“However” connects two independent clauses as a conjunctive adverb. Use a semicolon before it and a comma after it."},{"g":"Transitions","q":"The plan is inexpensive, and it requires little staff time. ______, small schools can implement it without creating a new department.","c":["Nevertheless","In contrast","Therefore","For example"],"a":2,"why":"The first two facts support the conclusion; “therefore” signals the logical result."}]},"rhetorical-strategy":{"session":11,"kind":"Reading","title":"Rhetorical Strategy","source":"Erica Meltzer, The Complete Guide to SAT Reading, p. 255","goal":"Rhetorical-strategy questions ask how a writer develops an argument or why the writer includes a quotation, example, anecdote, counterargument, paragraph, point-of-view shift, or change in focus.","sections":[{"h":"Five-step method","blocks":[{"t":"ol","x":["Locate the target and read around it, including at least one sentence before and after.","Summarize the target's content in a few words.","Name its rhetorical job: context, illustration, evidence, challenge, concession, qualification, or transition.","Connect that job to the author's larger purpose. Ask what the passage would lose without it.","Reject answers that only restate content, introduce unrelated material, exaggerate the evidence, or reverse the author's position."]}]},{"h":"Rhetorical jobs to recognize","blocks":[{"t":"table","x":{"head":["Job","Typical purpose"],"rows":[["Example / illustration","Makes an abstract claim concrete."],["Quotation","Supplies a viewpoint, claim, or idea the author will discuss, support, or challenge."],["Counterargument","Presents an opposing view so the author can respond."],["Concession","Acknowledges a limitation or valid opposing point before continuing."],["Paragraph structure","Moves from context to claim, evidence, objection, or response."],["Point of view","Shapes how information reaches the reader: personal experience or broader analysis."],["Contrast / shift","Makes a difference between ideas visible and marks a change in the argument."]]}}]},{"h":"EST 2026 alignment","blocks":[{"t":"p","x":"The 2026 EST I HS Literacy test integrates language use and reading comprehension: Module 1 (Writing), Module 2 (Reading), and Module 3 (Reading and Writing). Transition choice appears in Module 1, Question 16 and Module 3, Question 18. Rhetorical strategy appears in Module 2, Question 2; Module 2 Questions 10 and 11 ask about the use of an example or evidence, and Module 2 Question 21 asks about the passage's primary aim."},{"t":"p","x":"The transition item below includes its original options. The rhetorical-strategy prompt is reproduced without its option set; consult the supplied exam paper for those choices."}]}],"practice":[{"g":"Rhetorical Strategy","q":"Passage: A city's average temperature rose over a decade. To show how the change affected residents, the author describes a school that moved outdoor sports to mornings after several afternoons exceeded safety limits. Why include the school example?","c":["To shift to the history of school sports","To give a concrete example of how rising temperatures affect daily decisions","To prove every school stopped afternoon sports","To introduce an argument that temperatures have not changed"],"a":1,"why":"The school provides a specific illustration of the broader point about rising temperatures; it does not prove every school made the same change."},{"g":"Rhetorical Strategy","q":"Passage: Critics argue that remote work weakens collaboration. A survey of 600 employees found that teams with scheduled weekly meetings reported coordination levels similar to office-based teams. What role does the survey play?","c":["It proves remote work always improves collaboration","It introduces an unrelated issue","It provides evidence that qualifies the criticism of remote work","It explains why the critics originally supported remote work"],"a":2,"why":"The survey complicates the critics’ broad claim and supports a qualified conclusion, not an absolute one."},{"g":"Rhetorical Strategy","q":"Passage: The first paragraph describes a once-common belief that wetlands mainly create problems. The next explains how wetlands filter water, reduce flooding, and support wildlife. Why begin with the earlier belief?","c":["To introduce a misconception that the passage will correct","To establish that wetlands provide no useful services","To change the topic to local politics","To present the final conclusion before any evidence"],"a":0,"why":"The opening establishes the view that the following evidence will challenge."},{"g":"Rhetorical Strategy","q":"Passage: A historian notes that archives do not preserve every group's experiences equally. The author then contrasts detailed records kept by wealthy families with the scarcity of diaries written by laborers. What is the quotation's main function?","c":["To claim wealthy families never kept accurate records","To provide an unrelated definition of an archive","To frame the discussion of unequal representation in historical evidence","To argue historians should stop using written records"],"a":2,"why":"The quotation establishes the central problem that the examples develop: surviving records represent some groups more fully than others."},{"g":"Rhetorical Strategy","q":"Passage: I expected the new bridge to shorten the commute. After three weeks of observation, I found that traffic had shifted to neighboring streets rather than disappearing. How does the first-person account function?","c":["It proves all bridge projects fail","It provides a personal observation that complicates an initial expectation","It gives a complete history of bridge construction","It argues traffic never changes"],"a":1,"why":"The narrator’s experience contrasts the expected outcome with the observed result; it does not prove a universal rule."},{"g":"Rhetorical Strategy","q":"Passage: The first paragraph outlines the benefits of urban gardens. The second addresses concerns about maintenance. The third explains how shared volunteer schedules can address those concerns. How does this structure support the author's purpose?","c":["It presents benefits, acknowledges an objection, and responds with a practical solution","It lists unrelated facts","It rejects the benefits before discussing them","It presents the objection as the only valid position"],"a":0,"why":"The structure builds a balanced argument: benefits, concern, then response."}]},"drills-11":{"session":11,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 11, mixed together like the real exam.","sections":[],"practice":[{"g":"Drill Exercises","q":"The new filter removed most large particles. ______, it did not eliminate dissolved salts.","c":["Therefore","However","For example","Similarly"],"a":1,"why":"The second sentence limits the success described in the first, so a contrast transition fits.","ctx":[{"t":"p","x":"Choose the best answer, A–D. Questions 1–6 focus on transitions; Questions 7–12 focus on rhetorical strategy."}]},{"g":"Drill Exercises","q":"The first trial produced inconsistent readings; ______, the researchers calibrated the sensor before repeating it.","c":["consequently","nevertheless","similarly","for instance"],"a":0,"why":"The inconsistent readings prompted the calibration. “Consequently” signals the result; the semicolon and following comma are correct."},{"g":"Drill Exercises","q":"Some birds migrate thousands of kilometers. ______, the Arctic tern travels between polar regions each year.","c":["In contrast","For instance","Nevertheless","Consequently"],"a":1,"why":"The second sentence gives a specific example of the general statement."},{"g":"Drill Exercises","q":"The museum extended its opening hours; ______, attendance among working adults increased.","c":["as a result","on the other hand","for example","meanwhile"],"a":0,"why":"The second clause describes an outcome. Use a semicolon before the conjunctive transition and a comma after it."},{"g":"Drill Exercises","q":"Which sentence uses however correctly?","c":["The forecast looked clear, however, the team postponed the launch.","The forecast looked clear; however, the team postponed the launch.","The forecast looked clear however; the team postponed the launch.","The forecast looked clear; however the team, postponed the launch."],"a":1,"why":"“However” connects two independent clauses as a conjunctive adverb. Use a semicolon before it and a comma after it."},{"g":"Drill Exercises","q":"The plan is inexpensive, and it requires little staff time. ______, small schools can implement it without creating a new department.","c":["Nevertheless","In contrast","Therefore","For example"],"a":2,"why":"The first two facts support the conclusion; “therefore” signals the logical result."},{"g":"Drill Exercises","q":"Passage: A city's average temperature rose over a decade. To show how the change affected residents, the author describes a school that moved outdoor sports to mornings after several afternoons exceeded safety limits. Why include the school example?","c":["To shift to the history of school sports","To give a concrete example of how rising temperatures affect daily decisions","To prove every school stopped afternoon sports","To introduce an argument that temperatures have not changed"],"a":1,"why":"The school provides a specific illustration of the broader point about rising temperatures; it does not prove every school made the same change."},{"g":"Drill Exercises","q":"Passage: Critics argue that remote work weakens collaboration. A survey of 600 employees found that teams with scheduled weekly meetings reported coordination levels similar to office-based teams. What role does the survey play?","c":["It proves remote work always improves collaboration","It introduces an unrelated issue","It provides evidence that qualifies the criticism of remote work","It explains why the critics originally supported remote work"],"a":2,"why":"The survey complicates the critics’ broad claim and supports a qualified conclusion, not an absolute one."},{"g":"Drill Exercises","q":"Passage: The first paragraph describes a once-common belief that wetlands mainly create problems. The next explains how wetlands filter water, reduce flooding, and support wildlife. Why begin with the earlier belief?","c":["To introduce a misconception that the passage will correct","To establish that wetlands provide no useful services","To change the topic to local politics","To present the final conclusion before any evidence"],"a":0,"why":"The opening establishes the view that the following evidence will challenge."},{"g":"Drill Exercises","q":"Passage: A historian notes that archives do not preserve every group's experiences equally. The author then contrasts detailed records kept by wealthy families with the scarcity of diaries written by laborers. What is the quotation's main function?","c":["To claim wealthy families never kept accurate records","To provide an unrelated definition of an archive","To frame the discussion of unequal representation in historical evidence","To argue historians should stop using written records"],"a":2,"why":"The quotation establishes the central problem that the examples develop: surviving records represent some groups more fully than others."},{"g":"Drill Exercises","q":"Passage: I expected the new bridge to shorten the commute. After three weeks of observation, I found that traffic had shifted to neighboring streets rather than disappearing. How does the first-person account function?","c":["It proves all bridge projects fail","It provides a personal observation that complicates an initial expectation","It gives a complete history of bridge construction","It argues traffic never changes"],"a":1,"why":"The narrator’s experience contrasts the expected outcome with the observed result; it does not prove a universal rule."},{"g":"Drill Exercises","q":"Passage: The first paragraph outlines the benefits of urban gardens. The second addresses concerns about maintenance. The third explains how shared volunteer schedules can address those concerns. How does this structure support the author's purpose?","c":["It presents benefits, acknowledges an objection, and responds with a practical solution","It lists unrelated facts","It rejects the benefits before discussing them","It presents the objection as the only valid position"],"a":0,"why":"The structure builds a balanced argument: benefits, concern, then response."}]},"essential-clauses":{"session":12,"kind":"Grammar","title":"Non-Essential & Essential Clauses","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 113","goal":"A relative clause often begins with who, which, or that. Ask what job the clause performs, not just which word begins it.","sections":[{"h":"","blocks":[{"t":"table","x":{"head":["Type","Function","Punctuation"],"rows":[["Essential / restrictive","Identifies which person or thing the writer means; removing it changes or blurs the reference.","No commas."],["Non-essential / nonrestrictive","Adds extra information about a person or thing already identified.","Use commas around an interrupting clause."]]}}]},{"h":"Compare the meaning","blocks":[{"t":"p","x":"Essential: The students who submitted revisions received feedback. The clause identifies which students received feedback. Non-essential: The students, who had submitted revisions, received feedback. The clause adds information about the students already identified."}]},{"h":"Four-step punctuation check","blocks":[{"t":"ul","x":["Identify the noun the clause describes.","Ask whether the clause answers “which one(s)?” If yes, it is likely essential.","If the clause adds optional information, use a comma before and after it when it interrupts the main clause.","Read the sentence without the clause. If the reference becomes unclear or changes, the clause is likely essential. Usage reminder: In standard edited English, that normally introduces restrictive clauses; which commonly introduces nonrestrictive clauses. Who can introduce either type, depending on meaning."]}]},{"h":"EST MAY 2026 ALIGNMENT NOTE","blocks":[{"t":"p","x":"No directly matching May 2026 item was identified for essential/non-essential clauses. Module 1 Q23 tests relative-word selection in a clause, and Module 3 Q12 tests punctuation around an appositive phrase; these are adjacent skills, not direct tests. The supplied paper also did not yield a clearly paired-passage relationship question. All practice here is newly written, not mislabelled as official."}]}],"practice":[{"g":"Non-Essential & Essential Clauses","q":"Which sentence uses an essential (restrictive) relative clause correctly?","c":["Researchers, who work at the coastal station, record tides every hour.","Researchers who work at the coastal station record tides every hour.","Researchers who work at the coastal station, record tides every hour.","Researchers, who work at the coastal station record tides every hour."],"a":1,"why":"The clause identifies which researchers the sentence means. Because it restricts the noun, it takes no commas.","ctx":[{"t":"p","x":"Choose the best answer, A–D."}]},{"g":"Non-Essential & Essential Clauses","q":"Choose the correctly punctuated sentence.","c":["Dr. Sato who leads the project, will present the results on Friday.","Dr. Sato, who leads the project will present the results on Friday.","Dr. Sato, who leads the project, will present the results on Friday.","Dr. Sato who leads the project will present the results on Friday."],"a":2,"why":"The clause adds extra information about Dr. Sato, so commas mark both boundaries."},{"g":"Non-Essential & Essential Clauses","q":"What does the punctuation imply? “The students who submitted revisions received feedback.”","c":["Every student submitted revisions.","The clause identifies which students received feedback.","The clause is an optional comment about all students.","The sentence contains a punctuation error."],"a":1,"why":"Without commas, the clause identifies a subset: the students who submitted revisions."},{"g":"Non-Essential & Essential Clauses","q":"Choose the best punctuation: “The Amazon River ___ which crosses several countries ___ carries sediment toward the Atlantic.”","c":["comma / comma","no punctuation / comma","comma / no punctuation","no punctuation / no punctuation"],"a":0,"why":"The clause adds information about the already identified Amazon River, so commas mark both ends."},{"g":"Non-Essential & Essential Clauses","q":"A writer has two brothers and wants to identify the brother who lives in Amman. Which sentence is clearest?","c":["My brother, who lives in Amman, is visiting next week.","My brother who lives in Amman is visiting next week.","My brother, who lives in Amman is visiting next week.","My brother who lives in Amman, is visiting next week."],"a":1,"why":"The clause distinguishes one brother from the other, so it is essential and takes no commas."},{"g":"Non-Essential & Essential Clauses","q":"Which sentence correctly sets off a non-essential clause?","c":["The report which was published in May, includes three case studies.","The report, which was published in May includes three case studies.","The report, which was published in May, includes three case studies.","The report which, was published in May, includes three case studies."],"a":2,"why":"The publication date is extra information, so commas surround the clause."},{"g":"Non-Essential & Essential Clauses","q":"Which sentence follows standard punctuation for an essential clause?","c":["The books, that are on the top shelf, belong to the library.","The books that are on the top shelf belong to the library.","The books that are on the top shelf, belong to the library.","The books, that are on the top shelf belong to the library."],"a":1,"why":"The clause specifies which books. Essential clauses take no commas; standard edited English normally uses “that” for restrictive clauses."}]},"paired-passages":{"session":12,"kind":"Reading","title":"Paired Passages","source":"Erica Meltzer, The Complete Guide to SAT Reading, p. 276","goal":"Read both passages. A difference in emphasis does not automatically mean that the authors disagree.","sections":[{"h":"PASSAGE A — MEASURING THE BENEFIT OF STREET TREES","blocks":[{"t":"p","x":"City planners often describe street trees as a practical response to summer heat. In a two-year study, researchers measured afternoon temperatures on matched streets: one street had mature tree cover, while the other had little shade. The shaded streets were consistently cooler. The study does not show that trees solve every urban heat problem; building materials, traffic, and wind also affect local temperatures. Still, the repeated difference suggests that expanding tree cover can help reduce heat exposure, especially where residents spend time outdoors."}]},{"h":"PASSAGE B — DESIGNING A FAIR PLANTING PROGRAM","blocks":[{"t":"p","x":"A tree-planting campaign should be judged by more than the number of saplings planted. Young trees need water, pruning, and protection before they provide substantial shade. Cities should also map existing canopy cover before choosing planting sites. If wealthier districts already have mature trees while hotter, lower-income neighborhoods have few, equal numbers of new trees in every district will not necessarily produce equal benefits. A successful program therefore needs long-term maintenance and a clear priority for places with the greatest heat exposure and the least existing shade."}]},{"h":"Before answering: map each passage","blocks":[{"t":"ul","x":["Passage A: claim—tree cover can help reduce heat exposure; evidence—repeated temperature differences on matched streets; limit—other factors also affect temperature.","Passage B: claim—planting programs need targeted locations and long-term care; reasons—existing shade is unequal and young trees need maintenance.","Relationship: compatible. Passage A establishes a possible benefit; Passage B adds conditions for implementation."]}]}],"practice":[{"g":"Paired Passages","q":"Which statement best expresses Passage A’s central claim?","c":["Trees eliminate every source of urban heat.","Evidence from matched streets suggests that tree cover can help reduce heat exposure.","Wind is the only factor that affects street temperature.","Cities should stop measuring temperatures once they plant trees."],"a":1,"why":"Passage A uses matched-street measurements to support a limited claim about tree cover and acknowledges other influences.","ctx":[{"t":"note","x":"Both passages are needed for questions 8–14."},{"t":"p","x":"City planners often describe street trees as a practical response to summer heat. In a two-year study, researchers measured afternoon temperatures on matched streets: one street had mature tree cover, while the other had little shade. The shaded streets were consistently cooler. The study does not show that trees solve every urban heat problem; building materials, traffic, and wind also affect local temperatures. Still, the repeated difference suggests that expanding tree cover can help reduce heat exposure, especially where residents spend time outdoors."},{"t":"p","x":"A tree-planting campaign should be judged by more than the number of saplings planted. Young trees need water, pruning, and protection before they provide substantial shade. Cities should also map existing canopy cover before choosing planting sites. If wealthier districts already have mature trees while hotter, lower-income neighborhoods have few, equal numbers of new trees in every district will not necessarily produce equal benefits. A successful program therefore needs long-term maintenance and a clear priority for places with the greatest heat exposure and the least existing shade."}],"note":"Questions 8–14 require you to use one or both passages."},{"g":"Paired Passages","q":"Which concern most strongly shapes Passage B?","c":["Cities cannot grow trees in hot climates.","Tree planting has no measurable environmental value.","Planting totals alone may hide unequal access to shade and neglect of long-term care.","Mature trees should be removed before new saplings are planted."],"a":2,"why":"Passage B emphasizes existing shade, prioritizing high-need neighborhoods, and maintaining young trees."},{"g":"Paired Passages","q":"How do the passages relate to one another?","c":["Passage A questions whether trees affect temperature, while Passage B rejects all temperature data.","Passage A provides evidence for a benefit of tree cover; Passage B discusses how cities should implement planting fairly and effectively.","Passage B proves that the study in Passage A used false measurements.","Both passages argue that tree planting should be abandoned."],"a":1,"why":"The passages are compatible but emphasize different questions: whether tree cover can help and how a city should design a responsible program."},{"g":"Paired Passages","q":"Which claim would both authors most likely support?","c":["A city should plant the same number of trees in every neighborhood, regardless of need.","Trees alone can prevent all heat-related illness.","Tree-cover decisions should use evidence about local conditions rather than rely on assumptions.","A planting program succeeds as soon as saplings enter the ground."],"a":2,"why":"Passage A relies on temperature measurements and notes other factors; Passage B calls for mapping canopy and targeting need."},{"g":"Paired Passages","q":"How would the author of Passage B most likely respond to Passage A’s findings?","c":["The findings are irrelevant because street temperatures cannot be measured.","The findings are useful, but planners must also decide where trees are most needed and how to maintain them.","The findings prove that every neighborhood already receives equal benefits.","The findings show that maintenance makes no difference."],"a":1,"why":"Passage B does not reject the temperature benefit; it adds questions about location, equity, and maintenance."},{"g":"Paired Passages","q":"Which new finding would most directly strengthen Passage B’s recommendation to prioritize neighborhoods with little shade?","c":["Residents in low-canopy neighborhoods experience more days of dangerous outdoor heat than residents in well-shaded areas.","A nursery reports that it sells several species of ornamental trees.","A city archive lists the dates when parks first opened.","A study finds that tree leaves vary in shape across species."],"a":0,"why":"This directly connects low canopy cover to greater heat exposure, supporting the proposed priority."},{"g":"Paired Passages","q":"Which statement best captures a difference in the passages’ emphasis?","c":["Passage A emphasizes measured temperature differences; Passage B emphasizes planning, equity, and maintenance.","Passage A focuses on budgets; Passage B focuses on laboratory methods.","Passage A argues for removing trees; Passage B argues for keeping every tree.","Passage A discusses rural forests; Passage B discusses ocean temperatures."],"a":0,"why":"Passage A focuses on evidence that shade can lower street temperatures; Passage B focuses on the design and fairness of planting programs."}]},"drills-12":{"session":12,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 12, mixed together like the real exam.","sections":[],"practice":[{"g":"Clause Punctuation Practice","q":"Which sentence uses an essential (restrictive) relative clause correctly?","c":["Researchers, who work at the coastal station, record tides every hour.","Researchers who work at the coastal station record tides every hour.","Researchers who work at the coastal station, record tides every hour.","Researchers, who work at the coastal station record tides every hour."],"a":1,"why":"The clause identifies which researchers the sentence means. Because it restricts the noun, it takes no commas.","ctx":[{"t":"p","x":"Choose the best answer, A–D."}]},{"g":"Clause Punctuation Practice","q":"Choose the correctly punctuated sentence.","c":["Dr. Sato who leads the project, will present the results on Friday.","Dr. Sato, who leads the project will present the results on Friday.","Dr. Sato, who leads the project, will present the results on Friday.","Dr. Sato who leads the project will present the results on Friday."],"a":2,"why":"The clause adds extra information about Dr. Sato, so commas mark both boundaries."},{"g":"Clause Punctuation Practice","q":"What does the punctuation imply? “The students who submitted revisions received feedback.”","c":["Every student submitted revisions.","The clause identifies which students received feedback.","The clause is an optional comment about all students.","The sentence contains a punctuation error."],"a":1,"why":"Without commas, the clause identifies a subset: the students who submitted revisions."},{"g":"Clause Punctuation Practice","q":"Choose the best punctuation: “The Amazon River ___ which crosses several countries ___ carries sediment toward the Atlantic.”","c":["comma / comma","no punctuation / comma","comma / no punctuation","no punctuation / no punctuation"],"a":0,"why":"The clause adds information about the already identified Amazon River, so commas mark both ends."},{"g":"Clause Punctuation Practice","q":"A writer has two brothers and wants to identify the brother who lives in Amman. Which sentence is clearest?","c":["My brother, who lives in Amman, is visiting next week.","My brother who lives in Amman is visiting next week.","My brother, who lives in Amman is visiting next week.","My brother who lives in Amman, is visiting next week."],"a":1,"why":"The clause distinguishes one brother from the other, so it is essential and takes no commas."},{"g":"Clause Punctuation Practice","q":"Which sentence correctly sets off a non-essential clause?","c":["The report which was published in May, includes three case studies.","The report, which was published in May includes three case studies.","The report, which was published in May, includes three case studies.","The report which, was published in May, includes three case studies."],"a":2,"why":"The publication date is extra information, so commas surround the clause."},{"g":"Clause Punctuation Practice","q":"Which sentence follows standard punctuation for an essential clause?","c":["The books, that are on the top shelf, belong to the library.","The books that are on the top shelf belong to the library.","The books that are on the top shelf, belong to the library.","The books, that are on the top shelf belong to the library."],"a":1,"why":"The clause specifies which books. Essential clauses take no commas; standard edited English normally uses “that” for restrictive clauses."},{"g":"Paired-Passage Drill","q":"Which statement best expresses Passage A’s central claim?","c":["Trees eliminate every source of urban heat.","Evidence from matched streets suggests that tree cover can help reduce heat exposure.","Wind is the only factor that affects street temperature.","Cities should stop measuring temperatures once they plant trees."],"a":1,"why":"Passage A uses matched-street measurements to support a limited claim about tree cover and acknowledges other influences.","ctx":[{"t":"note","x":"Both passages are needed for questions 8–14."},{"t":"p","x":"City planners often describe street trees as a practical response to summer heat. In a two-year study, researchers measured afternoon temperatures on matched streets: one street had mature tree cover, while the other had little shade. The shaded streets were consistently cooler. The study does not show that trees solve every urban heat problem; building materials, traffic, and wind also affect local temperatures. Still, the repeated difference suggests that expanding tree cover can help reduce heat exposure, especially where residents spend time outdoors."},{"t":"p","x":"A tree-planting campaign should be judged by more than the number of saplings planted. Young trees need water, pruning, and protection before they provide substantial shade. Cities should also map existing canopy cover before choosing planting sites. If wealthier districts already have mature trees while hotter, lower-income neighborhoods have few, equal numbers of new trees in every district will not necessarily produce equal benefits. A successful program therefore needs long-term maintenance and a clear priority for places with the greatest heat exposure and the least existing shade."}],"note":"Questions 8–14 require you to use one or both passages."},{"g":"Paired-Passage Drill","q":"Which concern most strongly shapes Passage B?","c":["Cities cannot grow trees in hot climates.","Tree planting has no measurable environmental value.","Planting totals alone may hide unequal access to shade and neglect of long-term care.","Mature trees should be removed before new saplings are planted."],"a":2,"why":"Passage B emphasizes existing shade, prioritizing high-need neighborhoods, and maintaining young trees."},{"g":"Paired-Passage Drill","q":"How do the passages relate to one another?","c":["Passage A questions whether trees affect temperature, while Passage B rejects all temperature data.","Passage A provides evidence for a benefit of tree cover; Passage B discusses how cities should implement planting fairly and effectively.","Passage B proves that the study in Passage A used false measurements.","Both passages argue that tree planting should be abandoned."],"a":1,"why":"The passages are compatible but emphasize different questions: whether tree cover can help and how a city should design a responsible program."},{"g":"Paired-Passage Drill (Continued)","q":"Which claim would both authors most likely support?","c":["A city should plant the same number of trees in every neighborhood, regardless of need.","Trees alone can prevent all heat-related illness.","Tree-cover decisions should use evidence about local conditions rather than rely on assumptions.","A planting program succeeds as soon as saplings enter the ground."],"a":2,"why":"Passage A relies on temperature measurements and notes other factors; Passage B calls for mapping canopy and targeting need."},{"g":"Paired-Passage Drill (Continued)","q":"How would the author of Passage B most likely respond to Passage A’s findings?","c":["The findings are irrelevant because street temperatures cannot be measured.","The findings are useful, but planners must also decide where trees are most needed and how to maintain them.","The findings prove that every neighborhood already receives equal benefits.","The findings show that maintenance makes no difference."],"a":1,"why":"Passage B does not reject the temperature benefit; it adds questions about location, equity, and maintenance."},{"g":"Paired-Passage Drill (Continued)","q":"Which new finding would most directly strengthen Passage B’s recommendation to prioritize neighborhoods with little shade?","c":["Residents in low-canopy neighborhoods experience more days of dangerous outdoor heat than residents in well-shaded areas.","A nursery reports that it sells several species of ornamental trees.","A city archive lists the dates when parks first opened.","A study finds that tree leaves vary in shape across species."],"a":0,"why":"This directly connects low canopy cover to greater heat exposure, supporting the proposed priority."},{"g":"Paired-Passage Drill (Continued)","q":"Which statement best captures a difference in the passages’ emphasis?","c":["Passage A emphasizes measured temperature differences; Passage B emphasizes planning, equity, and maintenance.","Passage A focuses on budgets; Passage B focuses on laboratory methods.","Passage A argues for removing trees; Passage B argues for keeping every tree.","Passage A discusses rural forests; Passage B discusses ocean temperatures."],"a":0,"why":"Passage A focuses on evidence that shade can lower street temperatures; Passage B focuses on the design and fairness of planting programs."}]},"comma-uses":{"session":13,"kind":"Grammar","title":"Additional Comma Uses and Misuses","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 134","goal":"A comma should signal structure—not simply a pause. Use the patterns below to decide where commas belong.","sections":[{"h":"","blocks":[{"t":"table","x":{"head":["Use","Rule","Example"],"rows":[["Introductory element","After a substantial introductory phrase or clause","After checking the units, the analyst revised the chart."],["Series","Separate items in a list consistently","The survey recorded age, travel time, and preferred transport."],["Independent clauses","Use a comma before and, but, or, so, yet, for, nor when both sides are complete clauses","The sample was small, but the trend was consistent."],["Non-essential interruption","Use a pair of commas around optional information inserted into a sentence","The report, after a final review, was approved."],["Coordinate adjectives","Use a comma when adjectives independently describe the same noun","a careful, systematic method"],["Dates and places","Separate parts of a full date and city/state or city/country names with commas","October 12, 2025, in Jeddah, Saudi Arabia."]]}}]},{"h":"Three comma traps","blocks":[{"t":"ul","x":["Comma splice: two complete sentences joined by only a comma. Repair with a period, semicolon, or comma + coordinating conjunction.","Subject–verb split: do not place a comma between a subject and its verb just because the subject is long.","Essential information: do not surround a clause with commas when it identifies which person or thing the sentence means."]}]}],"practice":[{"g":"Additional Comma Uses and Misuses","q":"Choose the sentence with correct punctuation.","c":["The final report, after three rounds of review was approved by the committee.","The final report after three rounds of review, was approved by the committee.","The final report, after three rounds of review, was approved by the committee.","The final report after, three rounds of review, was approved by the committee."],"a":2,"why":"The phrase “after three rounds of review” interrupts the main clause and adds extra information. Place a comma before and after it.","ctx":[{"t":"p","x":"Choose the best answer, A–D."}]},{"g":"Additional Comma Uses and Misuses","q":"Which sentence correctly punctuates an introductory phrase?","c":["Before publishing the results the team checked every calculation.","Before publishing the results, the team checked every calculation.","Before, publishing the results the team checked every calculation.","Before publishing, the results the team checked every calculation."],"a":1,"why":"A comma separates the introductory phrase from the main clause."},{"g":"Additional Comma Uses and Misuses","q":"Choose the sentence that correctly uses commas in a series.","c":["The survey recorded age, travel time and, preferred transport.","The survey recorded age travel time, and preferred transport.","The survey recorded, age, travel time, and preferred transport.","The survey recorded age, travel time, and preferred transport."],"a":3,"why":"Use commas to separate items in a series. This handout uses the serial comma consistently."},{"g":"Additional Comma Uses and Misuses","q":"Which sentence correctly joins two independent clauses?","c":["The sample was small, but the trend was consistent.","The sample was small but, the trend was consistent.","The sample, was small but the trend was consistent.","The sample was small, the trend was consistent."],"a":0,"why":"Use a comma before a coordinating conjunction that joins two independent clauses. D is a comma splice."},{"g":"Additional Comma Uses and Misuses","q":"Which revision correctly fixes the comma splice? “The first chart shows annual totals, the second shows monthly averages.”","c":["The first chart shows annual totals, the second shows monthly averages.","The first chart shows annual totals, and the second shows monthly averages.","The first chart, shows annual totals and the second shows monthly averages.","The first chart shows, annual totals the second shows monthly averages."],"a":1,"why":"A comma plus a coordinating conjunction correctly joins the two independent clauses. A comma alone cannot join them."},{"g":"Additional Comma Uses and Misuses","q":"Which sentence avoids an incorrect comma between a subject and its verb?","c":["The researchers who conducted the interviews, published their findings in June.","The researchers, who conducted the interviews published their findings in June.","The researchers who conducted the interviews published their findings in June.","The researchers, who conducted the interviews, published, their findings in June."],"a":2,"why":"The clause identifies which researchers the sentence means, so it is essential and takes no commas. Do not place a comma between subject and verb."},{"g":"Additional Comma Uses and Misuses","q":"Which sentence correctly separates coordinate adjectives?","c":["The team used a careful systematic method.","The team used a careful, systematic method.","The team used a careful systematic, method.","The team used, a careful, systematic method."],"a":1,"why":"“Careful” and “systematic” independently describe “method.” The comma is appropriate because the adjectives are coordinate."},{"g":"Additional Comma Uses and Misuses","q":"Which sentence correctly punctuates the date and place?","c":["The conference began on October 12 2025 in Jeddah, Saudi Arabia.","The conference began on October 12, 2025 in Jeddah Saudi Arabia.","The conference began on October, 12, 2025, in Jeddah Saudi Arabia.","The conference began on October 12, 2025, in Jeddah, Saudi Arabia."],"a":3,"why":"In a month-day-year date, place a comma after the day and after the year when the sentence continues. Use a comma between city and country/state."}]},"graphics-data":{"session":13,"kind":"Reading","title":"Graphics and Data Analysis","source":"Erica Meltzer, The Complete Guide to SAT Reading, p. 300","goal":"The chart and table use newly created hypothetical data. Do not treat them as real-world research.","sections":[{"h":"","blocks":[{"t":"ul","x":["Read title and labels first: units, time period, categories, and scale.","Scan the pattern: rises, falls, peaks, gaps, and reversals.","Match the question to its source: graphic only, passage only, or both.","Calculate only what you need: subtract for a difference; divide part by total for a rate.","Do not claim causation from a pattern alone."]}]},{"h":"2026 EST alignment","blocks":[{"t":"p","x":"The 2026 EST HS Description Document includes visual evidence, evaluation of claims, and synthesis across text and visuals. The May 2026 paper includes a comma-related item in Module 1, Q33, and a graphic-interpretation item in Module 2, Q13. This handout cites those official items by reference only; it does not reproduce their wording or options."}]},{"h":"Afternoon surface temperature on two matched streets","blocks":[{"t":"img","src":"images/est/s13-street-temperature-graph.png","alt":"Line graph of afternoon surface temperature (°C) at 12:00, 1:00, 2:00 and 3:00. Shaded street: 32, 33, 34, 33. Mostly unshaded street: 36, 39, 41, 40."},{"t":"p","x":"Study note: Researchers chose streets with similar building density but did not control traffic volume or wind. The graph shows a pattern, not proof that shade was the only cause."}]},{"h":"Table 1 — Tree planting and survival after one year","blocks":[{"t":"table","x":{"head":["District","Planted","Surviving"],"rows":[["North District","80","60"],["Central District","100","85"],["South District","120","78"]]}},{"t":"p","x":"The table reports counts after 12 months. It does not report maintenance costs, tree species, or reasons for survival differences."}]},{"h":"Five-step graphics strategy","blocks":[{"t":"ul","x":["Read the title, labels, units, time period, and scale.","Scan for the main pattern: rise, fall, peak, gap, or reversal.","Match the question to its source: graphic only, passage only, or both.","Calculate only what you need: subtract for a difference; divide part by total for a rate.","Do not claim causation from a pattern alone."]}]}],"practice":[{"g":"Graphics and Data Analysis","q":"According to the line graph, when did the mostly unshaded street reach its highest recorded surface temperature?","c":["12:00","1:00","2:00","3:00"],"a":2,"why":"The unshaded line reaches its highest point at 2:00, at 41°C.","ctx":[{"t":"p","x":"Questions 9–13 use the line graph and study note. Questions 14–16 use the tree-survival table."},{"t":"img","src":"images/est/s13-street-temperature-graph.png","alt":"Line graph of afternoon surface temperature (°C) at 12:00, 1:00, 2:00 and 3:00. Shaded street: 32, 33, 34, 33. Mostly unshaded street: 36, 39, 41, 40."},{"t":"p","x":"Study note: Researchers chose streets with similar building density but did not control traffic volume or wind. The graph shows a pattern, not proof that shade was the only cause."}]},{"g":"Graphics and Data Analysis","q":"At which times was the temperature gap between the two streets greatest?","c":["12:00 only","1:00 only","2:00 and 3:00","The gap was the same at every time"],"a":2,"why":"The gaps are 4°C at 12:00, 6°C at 1:00, and 7°C at both 2:00 and 3:00."},{"g":"Graphics and Data Analysis","q":"Which statement best describes the shaded street’s pattern?","c":["Its temperature rose through 3:00 without falling.","Its temperature rose until 2:00, then fell slightly.","Its temperature stayed at 32°C all afternoon.","Its temperature fell at every measurement."],"a":1,"why":"The shaded street rises from 32°C to 34°C between 12:00 and 2:00, then drops to 33°C at 3:00."},{"g":"Graphics and Data Analysis","q":"Which conclusion is directly supported by the graph alone?","c":["The shaded street was cooler at all four recorded times.","Shade is the only factor that affects surface temperature.","Every shaded street in every city is cooler all year.","The unshaded street had less traffic at every time."],"a":0,"why":"At every plotted time, the shaded street’s temperature is lower. The graph does not establish the other claims."},{"g":"Graphics and Data Analysis","q":"Study note: The researchers chose streets with similar building density, but they did not control traffic volume or wind. Which interpretation best combines the note and the graph?","c":["The graph proves that shade alone caused every temperature difference.","The measurements show a consistent temperature difference, but other factors may also contribute.","The note makes the temperature measurements useless.","The graph proves that wind always cools unshaded streets."],"a":1,"why":"The graph shows a consistent difference; the note identifies uncontrolled factors, so the evidence supports a pattern but not a single certain cause."},{"g":"Graphics and Data Analysis","q":"According to the tree-survival table, which district had the highest survival rate?","c":["North District","Central District","South District","North and South had equal rates"],"a":1,"why":"Central District's rate is 85/100 = 85%, higher than North (75%) and South (65%).","ctx":[{"t":"h","x":"Table 1 — Tree planting and survival after one year"},{"t":"table","x":{"head":["District","Planted","Surviving"],"rows":[["North District","80","60"],["Central District","100","85"],["South District","120","78"]]}},{"t":"p","x":"The table reports counts after 12 months. It does not report maintenance costs, tree species, or reasons for survival differences."}]},{"g":"Graphics and Data Analysis","q":"How many trees survived across all three districts after one year?","c":["223","258","300","385"],"a":0,"why":"Add the survivors: 60 + 85 + 78 = 223."},{"g":"Graphics and Data Analysis","q":"Which conclusion is NOT justified by the table?","c":["Central District had the highest survival rate.","South District planted the largest number of trees.","More trees survived in Central District than in North District.","South District had the highest survival rate because it planted the most trees."],"a":3,"why":"South planted the most trees but had the lowest survival rate. The table cannot establish why the rates differ."}]},"drills-13":{"session":13,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 13, mixed together like the real exam.","sections":[],"practice":[{"g":"Comma Drill","q":"Choose the sentence with correct punctuation.","c":["The final report, after three rounds of review was approved by the committee.","The final report after three rounds of review, was approved by the committee.","The final report, after three rounds of review, was approved by the committee.","The final report after, three rounds of review, was approved by the committee."],"a":2,"why":"The phrase “after three rounds of review” interrupts the main clause and adds extra information. Place a comma before and after it.","ctx":[{"t":"p","x":"Choose the best answer, A–D."}]},{"g":"Comma Drill","q":"Which sentence correctly punctuates an introductory phrase?","c":["Before publishing the results the team checked every calculation.","Before publishing the results, the team checked every calculation.","Before, publishing the results the team checked every calculation.","Before publishing, the results the team checked every calculation."],"a":1,"why":"A comma separates the introductory phrase from the main clause."},{"g":"Comma Drill","q":"Choose the sentence that correctly uses commas in a series.","c":["The survey recorded age, travel time and, preferred transport.","The survey recorded age travel time, and preferred transport.","The survey recorded, age, travel time, and preferred transport.","The survey recorded age, travel time, and preferred transport."],"a":3,"why":"Use commas to separate items in a series. This handout uses the serial comma consistently."},{"g":"Comma Drill","q":"Which sentence correctly joins two independent clauses?","c":["The sample was small, but the trend was consistent.","The sample was small but, the trend was consistent.","The sample, was small but the trend was consistent.","The sample was small, the trend was consistent."],"a":0,"why":"Use a comma before a coordinating conjunction that joins two independent clauses. D is a comma splice."},{"g":"Comma Drill","q":"Which revision correctly fixes the comma splice? “The first chart shows annual totals, the second shows monthly averages.”","c":["The first chart shows annual totals, the second shows monthly averages.","The first chart shows annual totals, and the second shows monthly averages.","The first chart, shows annual totals and the second shows monthly averages.","The first chart shows, annual totals the second shows monthly averages."],"a":1,"why":"A comma plus a coordinating conjunction correctly joins the two independent clauses. A comma alone cannot join them."},{"g":"Comma Drill","q":"Which sentence avoids an incorrect comma between a subject and its verb?","c":["The researchers who conducted the interviews, published their findings in June.","The researchers, who conducted the interviews published their findings in June.","The researchers who conducted the interviews published their findings in June.","The researchers, who conducted the interviews, published, their findings in June."],"a":2,"why":"The clause identifies which researchers the sentence means, so it is essential and takes no commas. Do not place a comma between subject and verb."},{"g":"Comma Drill","q":"Which sentence correctly separates coordinate adjectives?","c":["The team used a careful systematic method.","The team used a careful, systematic method.","The team used a careful systematic, method.","The team used, a careful, systematic method."],"a":1,"why":"“Careful” and “systematic” independently describe “method.” The comma is appropriate because the adjectives are coordinate."},{"g":"Comma Drill","q":"Which sentence correctly punctuates the date and place?","c":["The conference began on October 12 2025 in Jeddah, Saudi Arabia.","The conference began on October 12, 2025 in Jeddah Saudi Arabia.","The conference began on October, 12, 2025, in Jeddah Saudi Arabia.","The conference began on October 12, 2025, in Jeddah, Saudi Arabia."],"a":3,"why":"In a month-day-year date, place a comma after the day and after the year when the sentence continues. Use a comma between city and country/state."},{"g":"Graphics And Data Drill","q":"According to the line graph, when did the mostly unshaded street reach its highest recorded surface temperature?","c":["12:00","1:00","2:00","3:00"],"a":2,"why":"The unshaded line reaches its highest point at 2:00, at 41°C.","ctx":[{"t":"p","x":"Questions 9–13 use the line graph and study note. Questions 14–16 use the tree-survival table."},{"t":"img","src":"images/est/s13-street-temperature-graph.png","alt":"Line graph of afternoon surface temperature (°C) at 12:00, 1:00, 2:00 and 3:00. Shaded street: 32, 33, 34, 33. Mostly unshaded street: 36, 39, 41, 40."},{"t":"p","x":"Study note: Researchers chose streets with similar building density but did not control traffic volume or wind. The graph shows a pattern, not proof that shade was the only cause."}]},{"g":"Graphics And Data Drill","q":"At which times was the temperature gap between the two streets greatest?","c":["12:00 only","1:00 only","2:00 and 3:00","The gap was the same at every time"],"a":2,"why":"The gaps are 4°C at 12:00, 6°C at 1:00, and 7°C at both 2:00 and 3:00."},{"g":"Graphics And Data Drill","q":"Which statement best describes the shaded street’s pattern?","c":["Its temperature rose through 3:00 without falling.","Its temperature rose until 2:00, then fell slightly.","Its temperature stayed at 32°C all afternoon.","Its temperature fell at every measurement."],"a":1,"why":"The shaded street rises from 32°C to 34°C between 12:00 and 2:00, then drops to 33°C at 3:00."},{"g":"Graphics And Data Drill","q":"Which conclusion is directly supported by the graph alone?","c":["The shaded street was cooler at all four recorded times.","Shade is the only factor that affects surface temperature.","Every shaded street in every city is cooler all year.","The unshaded street had less traffic at every time."],"a":0,"why":"At every plotted time, the shaded street’s temperature is lower. The graph does not establish the other claims."},{"g":"Graphics And Data Drill","q":"Study note: The researchers chose streets with similar building density, but they did not control traffic volume or wind. Which interpretation best combines the note and the graph?","c":["The graph proves that shade alone caused every temperature difference.","The measurements show a consistent temperature difference, but other factors may also contribute.","The note makes the temperature measurements useless.","The graph proves that wind always cools unshaded streets."],"a":1,"why":"The graph shows a consistent difference; the note identifies uncontrolled factors, so the evidence supports a pattern but not a single certain cause."},{"g":"Graphics And Data Drill","q":"According to the tree-survival table, which district had the highest survival rate?","c":["North District","Central District","South District","North and South had equal rates"],"a":1,"why":"Central District's rate is 85/100 = 85%, higher than North (75%) and South (65%).","ctx":[{"t":"h","x":"Table 1 — Tree planting and survival after one year"},{"t":"table","x":{"head":["District","Planted","Surviving"],"rows":[["North District","80","60"],["Central District","100","85"],["South District","120","78"]]}},{"t":"p","x":"The table reports counts after 12 months. It does not report maintenance costs, tree species, or reasons for survival differences."}]},{"g":"Graphics And Data Drill","q":"How many trees survived across all three districts after one year?","c":["223","258","300","385"],"a":0,"why":"Add the survivors: 60 + 85 + 78 = 223."},{"g":"Graphics And Data Drill","q":"Which conclusion is NOT justified by the table?","c":["Central District had the highest survival rate.","South District planted the largest number of trees.","More trees survived in Central District than in North District.","South District had the highest survival rate because it planted the most trees."],"a":3,"why":"South planted the most trees but had the lowest survival rate. The table cannot establish why the rates differ."}]},"colons-dashes":{"session":14,"kind":"Grammar","title":"Colons and Dashes","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 139","goal":"","sections":[{"h":"","blocks":[{"t":"table","x":{"head":["Mark","Use it when…","Example"],"rows":[["Colon (:)","The words before it form a complete sentence; what follows explains or lists.","The team needed one thing: reliable measurements."],["Colon (:)","A complete clause introduces a list.","Bring three items: a ruler, a notebook, and a calculator."],["Em dash (—)","Use a pair to set off an interruption inside a sentence.","The report—revised twice—was finally approved."],["Em dash (—)","A complete thought is followed by an emphatic explanation.","One problem remained—no one had checked the source."]]}}]},{"h":"Three punctuation traps","blocks":[{"t":"ul","x":["Do not put a colon directly after a verb or preposition just because a list follows.","Do not use a comma alone to join two independent clauses. A colon may introduce an explanation when the relationship makes sense.","Keep paired punctuation balanced: if two dashes mark an interruption, use both."]}]}],"practice":[{"g":"Colons and Dashes","q":"The review panel needs three documents ___ the budget, the schedule, and the safety plan.","c":["comma","colon","question mark","apostrophe"],"a":1,"why":"The words before the blank form a complete sentence. A colon introduces the list.","ctx":[{"t":"p","x":"Questions 1–7 are newly written. Choose the best answer, A–D."}]},{"g":"Colons and Dashes","q":"Which sentence uses a colon correctly?","c":["The result was clear: the second trial produced the same pattern.","The result was: clear after the second trial.","The result: was clear after the second trial.","The result was clear the second trial: produced the same pattern."],"a":0,"why":"A colon can introduce an explanation after a complete clause. The other choices split a verb phrase or clause."},{"g":"Colons and Dashes","q":"Choose the correctly punctuated sentence.","c":["The lab collected: soil, water, and air samples.","The lab collected soil, water, and air samples.","The lab collected soil: water, and air samples.","The lab collected soil, water: and air samples."],"a":1,"why":"Do not put a colon directly after a verb that introduces its object."},{"g":"Colons and Dashes","q":"Which sentence correctly uses paired dashes to set off an interruption?","c":["The archive's oldest map—drawn in 1842—shows the river before the bridge was built.","The archive's oldest map, drawn in 1842—shows the river before the bridge was built.","The archive's oldest map—drawn in 1842, shows the river before the bridge was built.","The archive's oldest map drawn—in 1842—shows the river before the bridge was built."],"a":0,"why":"Two dashes mark both boundaries of the interruption. Do not mix a comma with a dash at one boundary."},{"g":"Colons and Dashes","q":"Which punctuation best introduces the explanation after the complete clause?","c":["The team reached one conclusion, the sensor needed recalibration.","The team reached one conclusion: the sensor needed recalibration.","The team reached one: conclusion the sensor needed recalibration.","The team reached one conclusion the sensor: needed recalibration."],"a":1,"why":"The second clause explains the conclusion. A colon introduces the explanation; a comma alone would create a comma splice."},{"g":"Colons and Dashes","q":"Choose the sentence in which a dash adds emphasis after a complete thought.","c":["One factor mattered most—consistent follow-up.","One factor—mattered most consistent follow-up.","One factor mattered—most consistent follow-up.","One factor mattered most, consistent follow-up."],"a":0,"why":"The dash introduces an emphatic explanation of the preceding thought."},{"g":"Colons and Dashes","q":"Which sentence punctuates an indirect question correctly?","c":["The editor asked, whether the source had been verified?","The editor asked whether the source had been verified.","The editor asked whether had the source been verified?","The editor asked: whether the source had been verified?"],"a":1,"why":"An indirect question uses statement word order and usually ends with a period when the sentence reports rather than asks."}]},"question-marks":{"session":14,"kind":"Grammar","title":"Question Marks","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 143","goal":"A direct question takes a question mark. An indirect question usually stays inside a statement and takes a period: The editor asked whether the source had been verified. In a reading passage, a question mark may:","sections":[{"h":"","blocks":[{"t":"ul","x":["frame the central issue the author will discuss;","challenge an assumption or signal skepticism;","set up a question that the next sentence answers;","highlight a trade-off or gap in the evidence. Reading shortcut: Read the sentence before and after the question. Ask what assumption it tests, what problem it introduces, and whether the author answers it."]}]},{"h":"OFFICIAL MAY 2026 EST ALIGNMENT","blocks":[{"t":"p","x":"Module 1, Q35 tests selection of terminal punctuation in a sentence. Its context is needed, so this handout references it without reproducing the wording or choices. No directly matching item was identified for colon/dash usage or question marks as rhetorical reading cues. All drills below are newly written."}]}],"practice":[{"g":"Question Marks","q":"Excerpt: ““The city calls the project a success. But is a ribbon-cutting ceremony proof that residents can reach work faster?”” What is the question mark most likely helping the author do?","c":["Express unquestioning support for the project","Challenge whether the evidence proves the city’s claim","Introduce a list of project costs","Signal that the passage has ended"],"a":1,"why":"The question challenges the assumption that a public ceremony proves a practical outcome; the context signals skepticism.","ctx":[{"t":"p","x":"Questions 8–14 are newly written. Read each excerpt, then choose the best answer."}]},{"g":"Question Marks","q":"Excerpt: ““What would happen if the river rose another meter? The town’s emergency plan answers part of that question, but not every neighborhood has an evacuation route.”” What role does the opening question play?","c":["It frames the central problem the paragraph will examine.","It proves that the river will rise another meter.","It gives a fact that needs no further evidence.","It signals that the author rejects all emergency planning."],"a":0,"why":"The question introduces flood preparedness; the following sentences begin to answer it and note a limitation."},{"g":"Question Marks","q":"Excerpt: ““If the policy is so effective, why did complaints rise after it began? The agency should compare complaint records with other changes that occurred during the same period.”” The question mark primarily signals that the author is…","c":["certain that the policy caused every complaint","asking for a definition of a familiar word","skeptical of an unsupported claim and calling for stronger evidence","changing to an unrelated topic"],"a":2,"why":"The rhetorical question highlights a tension between the policy’s claimed success and rising complaints."},{"g":"Question Marks","q":"Excerpt: ““Which measure matters most—speed, cost, or reliability? The next section compares all three before recommending a route.”” How does the question function in the passage?","c":["It introduces the comparison that organizes the discussion.","It announces that reliability is unimportant.","It provides the final recommendation.","It shows that the author has no criteria for comparison."],"a":0,"why":"The question establishes the criteria the next section will compare."},{"g":"Question Marks","q":"Excerpt: ““The museum’s new wing drew large crowds. Does attendance alone prove that visitors learned more? No: surveys must also measure what visitors understood.”” What assumption does the question challenge?","c":["Museums can attract visitors.","Attendance numbers automatically measure learning.","Surveys can collect information.","New buildings require maintenance."],"a":1,"why":"The author questions whether high attendance is sufficient evidence of learning."},{"g":"Question Marks","q":"Excerpt: ““The machine can sort thousands of parcels per hour—but at what cost to accuracy? In the trial, speed increased while the error rate rose slightly.”” The question mark helps emphasize which issue?","c":["Whether the machine has enough storage space","The trade-off between speed and accuracy","Whether parcels should be delivered by boat","The history of sorting machines"],"a":1,"why":"The question raises the cost to accuracy; the next sentence shows a speed–accuracy trade-off."},{"g":"Question Marks","q":"Excerpt: ““Why did the first trial fail? The team found a flaw in the sensor, not in the underlying design.”” What is the most likely function of the question?","c":["It introduces a problem that the next sentence answers.","It expresses doubt that any trial took place.","It signals that the author will list unrelated examples.","It proves that the design can never work."],"a":0,"why":"The question raises a problem, and the next sentence supplies the explanation."}]},"drills-14":{"session":14,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 14, mixed together like the real exam.","sections":[],"practice":[{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"The review panel needs three documents ___ the budget, the schedule, and the safety plan.","c":["comma","colon","question mark","apostrophe"],"a":1,"why":"The words before the blank form a complete sentence. A colon introduces the list.","ctx":[{"t":"p","x":"Questions 1–7 are newly written. Choose the best answer, A–D."}]},{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"Which sentence uses a colon correctly?","c":["The result was clear: the second trial produced the same pattern.","The result was: clear after the second trial.","The result: was clear after the second trial.","The result was clear the second trial: produced the same pattern."],"a":0,"why":"A colon can introduce an explanation after a complete clause. The other choices split a verb phrase or clause."},{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"Choose the correctly punctuated sentence.","c":["The lab collected: soil, water, and air samples.","The lab collected soil, water, and air samples.","The lab collected soil: water, and air samples.","The lab collected soil, water: and air samples."],"a":1,"why":"Do not put a colon directly after a verb that introduces its object."},{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"Which sentence correctly uses paired dashes to set off an interruption?","c":["The archive's oldest map—drawn in 1842—shows the river before the bridge was built.","The archive's oldest map, drawn in 1842—shows the river before the bridge was built.","The archive's oldest map—drawn in 1842, shows the river before the bridge was built.","The archive's oldest map drawn—in 1842—shows the river before the bridge was built."],"a":0,"why":"Two dashes mark both boundaries of the interruption. Do not mix a comma with a dash at one boundary."},{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"Which punctuation best introduces the explanation after the complete clause?","c":["The team reached one conclusion, the sensor needed recalibration.","The team reached one conclusion: the sensor needed recalibration.","The team reached one: conclusion the sensor needed recalibration.","The team reached one conclusion the sensor: needed recalibration."],"a":1,"why":"The second clause explains the conclusion. A colon introduces the explanation; a comma alone would create a comma splice."},{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"Choose the sentence in which a dash adds emphasis after a complete thought.","c":["One factor mattered most—consistent follow-up.","One factor—mattered most consistent follow-up.","One factor mattered—most consistent follow-up.","One factor mattered most, consistent follow-up."],"a":0,"why":"The dash introduces an emphatic explanation of the preceding thought."},{"g":"Colons, Dashes, And Question-Mark Punctuation Drill","q":"Which sentence punctuates an indirect question correctly?","c":["The editor asked, whether the source had been verified?","The editor asked whether the source had been verified.","The editor asked whether had the source been verified?","The editor asked: whether the source had been verified?"],"a":1,"why":"An indirect question uses statement word order and usually ends with a period when the sentence reports rather than asks."},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““The city calls the project a success. But is a ribbon-cutting ceremony proof that residents can reach work faster?”” What is the question mark most likely helping the author do?","c":["Express unquestioning support for the project","Challenge whether the evidence proves the city’s claim","Introduce a list of project costs","Signal that the passage has ended"],"a":1,"why":"The question challenges the assumption that a public ceremony proves a practical outcome; the context signals skepticism.","ctx":[{"t":"p","x":"Questions 8–14 are newly written. Read each excerpt, then choose the best answer."}]},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““What would happen if the river rose another meter? The town’s emergency plan answers part of that question, but not every neighborhood has an evacuation route.”” What role does the opening question play?","c":["It frames the central problem the paragraph will examine.","It proves that the river will rise another meter.","It gives a fact that needs no further evidence.","It signals that the author rejects all emergency planning."],"a":0,"why":"The question introduces flood preparedness; the following sentences begin to answer it and note a limitation."},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““If the policy is so effective, why did complaints rise after it began? The agency should compare complaint records with other changes that occurred during the same period.”” The question mark primarily signals that the author is…","c":["certain that the policy caused every complaint","asking for a definition of a familiar word","skeptical of an unsupported claim and calling for stronger evidence","changing to an unrelated topic"],"a":2,"why":"The rhetorical question highlights a tension between the policy’s claimed success and rising complaints."},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““Which measure matters most—speed, cost, or reliability? The next section compares all three before recommending a route.”” How does the question function in the passage?","c":["It introduces the comparison that organizes the discussion.","It announces that reliability is unimportant.","It provides the final recommendation.","It shows that the author has no criteria for comparison."],"a":0,"why":"The question establishes the criteria the next section will compare."},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““The museum’s new wing drew large crowds. Does attendance alone prove that visitors learned more? No: surveys must also measure what visitors understood.”” What assumption does the question challenge?","c":["Museums can attract visitors.","Attendance numbers automatically measure learning.","Surveys can collect information.","New buildings require maintenance."],"a":1,"why":"The author questions whether high attendance is sufficient evidence of learning."},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““The machine can sort thousands of parcels per hour—but at what cost to accuracy? In the trial, speed increased while the error rate rose slightly.”” The question mark helps emphasize which issue?","c":["Whether the machine has enough storage space","The trade-off between speed and accuracy","Whether parcels should be delivered by boat","The history of sorting machines"],"a":1,"why":"The question raises the cost to accuracy; the next sentence shows a speed–accuracy trade-off."},{"g":"Reading Drill: What Does The Question Mark Signal?","q":"Excerpt: ““Why did the first trial fail? The team found a flaw in the sensor, not in the underlying design.”” What is the most likely function of the question?","c":["It introduces a problem that the next sentence answers.","It expresses doubt that any trial took place.","It signals that the author will list unrelated examples.","It proves that the design can never work."],"a":0,"why":"The question raises a problem, and the next sentence supplies the explanation."}]},"apostrophes":{"session":15,"kind":"Grammar","title":"Apostrophes: Plural vs. Possessive","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 144","goal":"","sections":[{"h":"","blocks":[{"t":"table","x":{"head":["Meaning","Rule","Example"],"rows":[["One owner","Singular noun + 's","the scientist's notebook"],["Several owners; plural ends in -s","Plural noun + apostrophe","the scientists' reports"],["Irregular plural; no final -s","Plural noun + 's","the children's project"],["Plural only; no ownership","Usually add -s or -es; no apostrophe","three students; two laboratories"],["Possessive pronoun","its = belonging to it","The machine lost its power."],["Contraction","it's = it is / it has","It's ready. / It's been tested."],["Ownership question","whose = belonging to whom","Whose notebook is this?"],["Contraction","who's = who is / who has","Who's ready to begin?"]]}}]},{"h":"THE 3-SECOND APOSTROPHE CHECK","blocks":[{"t":"ul","x":["Ask whether the noun is simply plural or owns something.","If it owns something, find the owner: one scientist fi scientist's; several scientists fi scientists'.","If you see it's, test “it is” or “it has.” If neither fits, use its.","Never add an apostrophe to a plain plural: reports, teachers, libraries."]}]}],"practice":[{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the correctly punctuated sentence. The ___ notebook contained the original measurements.","c":["scientist's","scientists'","scientists","scientist"],"a":0,"why":"One scientist owns the notebook, so the singular noun takes apostrophe + s: scientist's.","ctx":[{"t":"p","x":"Questions 1–8 are newly written. Choose the best answer, A–D."}]},{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the best form to complete the sentence.The ___ reports, one from each of three scientists, arrived before noon.","c":["scientist's","scientists'","scientists","scientist"],"a":1,"why":"More than one scientist owns or produced the reports. For a regular plural ending in -s, add only an apostrophe: scientists'."},{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the correctly written possessive. The ___ science fair begins tomorrow.","c":["childrens'","children's","childrens","childrens's"],"a":1,"why":"Children is an irregular plural that does not end in -s. Add apostrophe + s: children's."},{"g":"Apostrophes: Plural vs. Possessive","q":"Which sentence is correct?","c":["The student's were excited about the new microscopes.","The students were excited about the new microscopes.","The students' were excited about the new microscopes.","The student were excited about the new microscopes."],"a":1,"why":"Students is simply plural here; it does not show ownership, so it needs no apostrophe."},{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the correct word. The machine lost ___ power when the cable came loose.","c":["it's","its","its'","its's"],"a":1,"why":"Its is the possessive form. It's means it is or it has."},{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the correct form. ___ important to label each sample before storage.","c":["Its","It's","Its'","Its's"],"a":1,"why":"It's is the contraction of it is: “It is important…” Its shows possession."},{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the correct word. ___ notebook was left in the laboratory?","c":["Who's","Whose","Whos'","Whose's"],"a":1,"why":"Whose asks who owns something. Who's means who is or who has."},{"g":"Apostrophes: Plural vs. Possessive","q":"Choose the correctly punctuated sentence.","c":["The editor-in-chief decision was final.","The editor-in-chief's decision was final.","The editors-in-chief decision was final.","The editor's-in-chief decision was final."],"a":1,"why":"The singular compound noun editor-in-chief takes the possessive apostrophe at the end: editor-in-chief's."}]},"pronoun-noun-agreement":{"session":15,"kind":"Grammar","title":"Pronoun and Noun Agreement","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 153","goal":"A pronoun must match the noun or noun phrase it refers to. That noun is the antecedent. Check number first: singular antecedent fi singular pronoun; plural antecedent fi plural pronoun.","sections":[{"h":"Matching pronouns to antecedents","blocks":[{"t":"table","x":{"head":["Antecedent","Matching pronoun","Example"],"rows":[["the company (one organization)","it / its","The company revised its policy."],["the volunteers (plural)","they / their","The volunteers returned their badges."],["the coach and the players","they / their","They agreed to arrive early."],["each / neither (singular in formal test grammar)","it / its, where natural","Each folder has its own label."],["the committee / team acting as one unit","it / its in American English","The committee announced its decision."]]}}]},{"h":"EXAM STRATEGY","blocks":[{"t":"ul","x":["Circle the antecedent before looking at the choices.","Replace each option in the sentence and check whether it matches the antecedent.","their shows possession; there refers to a place or introduces a clause; they're means they are.","Check meaning as well as number: a pronoun can match in number yet refer to the wrong noun."]}]}],"practice":[{"g":"Pronoun and Noun Agreement","q":"Choose the pronoun that agrees with the noun. The company revised ___ policy after the audit.","c":["their","its","it's","them"],"a":1,"why":"Company is singular and acts as one organization here, so the singular possessive pronoun its agrees.","ctx":[{"t":"p","x":"Questions 9–16 are newly written. Choose the best answer, A–D."}]},{"g":"Pronoun and Noun Agreement","q":"Choose the pronoun that agrees with the noun. The two volunteers returned ___ badges at the front desk.","c":["its","it's","their","them's"],"a":2,"why":"Volunteers is plural, so their is the matching possessive pronoun."},{"g":"Pronoun and Noun Agreement","q":"Choose the best completion. Neither of the microscopes was ready because ___ lens was cracked.","c":["their","it's","its","them"],"a":2,"why":"Neither is singular in this construction. Its refers to the singular microscope being discussed."},{"g":"Pronoun and Noun Agreement","q":"Choose the pronoun that agrees with the compound subject. The coach and the players agreed that ___ would arrive early.","c":["it","they","its","he"],"a":1,"why":"The coach and the players form a compound subject joined by and, so they is plural."},{"g":"Pronoun and Noun Agreement","q":"Choose the pronoun that agrees with the noun. The committee announced ___ decision after a long meeting.","c":["it's","their","its","they"],"a":2,"why":"In this sentence, the committee acts as one body making one decision. Use its."},{"g":"Pronoun and Noun Agreement","q":"Choose the correct completion. Each of the folders has ___ own label.","c":["their","they","its","it's"],"a":2,"why":"Each is grammatically singular, so its agrees with the antecedent each."},{"g":"Pronoun and Noun Agreement","q":"Choose the pronoun that agrees with the noun. The novels were returned after ___ covers were repaired.","c":["its","it's","their","them"],"a":2,"why":"Novels is plural, so their correctly refers to the covers belonging to those novels."},{"g":"Pronoun and Noun Agreement","q":"Choose the best completion. The research team updated ___ records before publishing the report.","c":["their","it's","its","them's"],"a":2,"why":"The team is treated as one unit in this American-English sentence, so its is the expected agreement form."}]},"drills-15":{"session":15,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 15, mixed together like the real exam.","sections":[],"practice":[{"g":"Practice Drill A: Apostrophes","q":"Choose the correctly punctuated sentence. The ___ notebook contained the original measurements.","c":["scientist's","scientists'","scientists","scientist"],"a":0,"why":"One scientist owns the notebook, so the singular noun takes apostrophe + s: scientist's.","ctx":[{"t":"p","x":"Questions 1–8 are newly written. Choose the best answer, A–D."}]},{"g":"Practice Drill A: Apostrophes","q":"Choose the best form to complete the sentence.The ___ reports, one from each of three scientists, arrived before noon.","c":["scientist's","scientists'","scientists","scientist"],"a":1,"why":"More than one scientist owns or produced the reports. For a regular plural ending in -s, add only an apostrophe: scientists'."},{"g":"Practice Drill A: Apostrophes","q":"Choose the correctly written possessive. The ___ science fair begins tomorrow.","c":["childrens'","children's","childrens","childrens's"],"a":1,"why":"Children is an irregular plural that does not end in -s. Add apostrophe + s: children's."},{"g":"Practice Drill A: Apostrophes","q":"Which sentence is correct?","c":["The student's were excited about the new microscopes.","The students were excited about the new microscopes.","The students' were excited about the new microscopes.","The student were excited about the new microscopes."],"a":1,"why":"Students is simply plural here; it does not show ownership, so it needs no apostrophe."},{"g":"Practice Drill A: Apostrophes","q":"Choose the correct word. The machine lost ___ power when the cable came loose.","c":["it's","its","its'","its's"],"a":1,"why":"Its is the possessive form. It's means it is or it has."},{"g":"Practice Drill A: Apostrophes","q":"Choose the correct form. ___ important to label each sample before storage.","c":["Its","It's","Its'","Its's"],"a":1,"why":"It's is the contraction of it is: “It is important…” Its shows possession."},{"g":"Practice Drill A: Apostrophes","q":"Choose the correct word. ___ notebook was left in the laboratory?","c":["Who's","Whose","Whos'","Whose's"],"a":1,"why":"Whose asks who owns something. Who's means who is or who has."},{"g":"Practice Drill A: Apostrophes","q":"Choose the correctly punctuated sentence.","c":["The editor-in-chief decision was final.","The editor-in-chief's decision was final.","The editors-in-chief decision was final.","The editor's-in-chief decision was final."],"a":1,"why":"The singular compound noun editor-in-chief takes the possessive apostrophe at the end: editor-in-chief's."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the pronoun that agrees with the noun. The company revised ___ policy after the audit.","c":["their","its","it's","them"],"a":1,"why":"Company is singular and acts as one organization here, so the singular possessive pronoun its agrees.","ctx":[{"t":"p","x":"Questions 9–16 are newly written. Choose the best answer, A–D."}]},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the pronoun that agrees with the noun. The two volunteers returned ___ badges at the front desk.","c":["its","it's","their","them's"],"a":2,"why":"Volunteers is plural, so their is the matching possessive pronoun."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the best completion. Neither of the microscopes was ready because ___ lens was cracked.","c":["their","it's","its","them"],"a":2,"why":"Neither is singular in this construction. Its refers to the singular microscope being discussed."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the pronoun that agrees with the compound subject. The coach and the players agreed that ___ would arrive early.","c":["it","they","its","he"],"a":1,"why":"The coach and the players form a compound subject joined by and, so they is plural."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the pronoun that agrees with the noun. The committee announced ___ decision after a long meeting.","c":["it's","their","its","they"],"a":2,"why":"In this sentence, the committee acts as one body making one decision. Use its."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the correct completion. Each of the folders has ___ own label.","c":["their","they","its","it's"],"a":2,"why":"Each is grammatically singular, so its agrees with the antecedent each."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the pronoun that agrees with the noun. The novels were returned after ___ covers were repaired.","c":["its","it's","their","them"],"a":2,"why":"Novels is plural, so their correctly refers to the covers belonging to those novels."},{"g":"Practice Drill B: Pronoun And Noun Agreement","q":"Choose the best completion. The research team updated ___ records before publishing the report.","c":["their","it's","its","them's"],"a":2,"why":"The team is treated as one unit in this American-English sentence, so its is the expected agreement form."}]},"verbs-agreement-tense":{"session":16,"kind":"Grammar","title":"Verbs: Agreement and Tense","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 170","goal":"","sections":[{"h":"Learning targets","blocks":[{"t":"ul","x":["Find the true subject before choosing a verb.","Keep verb tense consistent with time markers and the sequence of events.","Recognize common word pairs that differ in meaning or grammatical role.","Apply these choices in short editing-in-context questions modeled on EST Module 1."]}]},{"h":"Subject–verb agreement patterns","blocks":[{"t":"table","x":{"head":["Pattern","Rule","Example"],"rows":[["Singular subject","Use a singular verb.","The collection is complete."],["Plural subject","Use a plural verb.","The records are complete."],["Subject + extra phrase","Ignore a phrase between subject and verb.","The box of samples is sealed."],["Each / neither / a series","Treat the grammatical head as singular in formal test editing.","Each of the samples was stored."],["Compound subject with and","Usually use a plural verb.","The coach and players are ready."]]}}]},{"h":"Tense signals","blocks":[{"t":"table","x":{"head":["Signal","Likely choice","Example"],"rows":[["A completed past time (yesterday, last spring)","Simple past","The river rose last spring."],["One past event before another past event","Past perfect for the earlier event","The storm had ended before they arrived."],["A general fact or current finding","Simple present","The material expands when heated."],["An action in progress at a past moment","Past progressive","They were preparing the report when power failed."]]}}]},{"h":"Fast strategy","blocks":[{"t":"ul","x":["Circle the subject; cross out prepositional phrases such as of the samples or along with the director.","Underline time markers and locate the main event. Ask which action happened first.","Do not change tense just because the passage contains another tense; change it only when the time relationship requires it."]}]}],"practice":[{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. Neither of the proposals ___ approved by the committee yesterday.","c":["were","was","are","have been"],"a":1,"why":"Neither is singular in formal test grammar. The time marker yesterday requires past tense, so was is correct.","ctx":[{"t":"p","x":"Questions 1–8 are newly written. Choose the best answer, A–D."}]},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. The collection of field notes, maps, and photographs ___ in the archive.","c":["are","were","is","have been"],"a":2,"why":"The subject is collection, not the plural nouns in the prepositional phrase. Collection is singular, so use is."},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. The researchers, along with the laboratory director, ___ preparing the report when the power failed.","c":["was","were","is","has been"],"a":1,"why":"The main subject is researchers. The phrase along with the laboratory director does not change its plural number. The past-progressive form were preparing fits the time frame."},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb form. By the time the team reached the site, the storm ___.","c":["ends","has ended","had ended","will end"],"a":2,"why":"The storm ended before another past event (the team's arrival). The past perfect, had ended, makes that earlier sequence clear."},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. Each of the samples ___ stored at a different temperature during the experiment.","c":["were","have been","was","are"],"a":2,"why":"Each is singular, even when followed by a plural noun in an of-phrase. The sentence describes a past experiment, so was is correct."},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. The report describes how the river ___ after heavy rainfall last spring.","c":["rises","rose","has risen","will rise"],"a":1,"why":"Last spring identifies a completed past event. Rose is the simple-past form and keeps the time reference consistent."},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. A series of tests ___ that the material expands when heated.","c":["show","shows","were showing","have shown"],"a":1,"why":"The subject is the singular phrase a series. The sentence states a general finding, so the simple-present singular verb shows fits."},{"g":"Verbs: Agreement and Tense","q":"Choose the best verb. When the scientist repeated the trial, she discovered that the first reading ___ inaccurate.","c":["is","has been","was","will be"],"a":2,"why":"The sentence narrates past events. Was keeps the discovered result in the same past-time frame."}]},"word-pairs":{"session":16,"kind":"Grammar","title":"Word Pairs and Comparisons","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 193","goal":"Choose by meaning and grammatical role, not by sound. Learn the contrast in each row.","sections":[{"h":"","blocks":[{"t":"table","x":{"head":["Pair","Difference","Quick example"],"rows":[["affect / effect","affect = usually a verb; effect = usually a noun","Heat can affect the sample; the effect was small."],["accept / except","accept = receive; except = excluding","We accept all entries except late ones."],["than / then","than = comparison; then = time or sequence","This result is higher than the first; then record it."],["principal / principle","principal = leader or primary; principle = rule or idea","The principal explained the principle."],["complement / compliment","complement = complete or enhance; compliment = praise","The colors complement each other."],["stationary / stationery","stationary = not moving; stationery = writing supplies","The stationary bicycle stood by the stationery cabinet."],["cite / site / sight","cite = reference; site = location; sight = seeing or something seen","Cite the source; visit the site; keep it in sight."],["allusion / illusion","allusion = indirect reference; illusion = misleading appearance","The writer made an allusion, not an illusion."]]}}]},{"h":"Official May 2026 EST alignment","blocks":[{"t":"p","x":"Module 1, Question 31 directly tests subject–verb agreement. The original item contains a plural subject followed by a verb that must agree; its answer is C (form). For copyright control, the short excerpt and original prompt/options below total fewer than 25 quoted words. Official May 2026 item — Module 1, Q31: Excerpt: “These movements [31] forms lines” Prompt: “Which option is the most grammatically correct?” A. NO CHANGE B. forming C. form D. formed Official answer: C. form. “Movements” is plural, so it takes “form,” not “forms.” Module 1, Question 19 also tests verb tense in a past-tense narrative; consult the original paper for the full item. No directly matching May 2026 item was identified for the listed commonly confused word pairs, so Questions 9–16 are newly written. Format note: The 2026 EST description defines Module 1 as Writing, with editing tasks that assess grammatical accuracy and effective language use. The handout therefore teaches rules briefly, then applies them in sentence-level editing questions."}]}],"practice":[{"g":"Word Pairs and Comparisons","q":"The new filter may ___ the amount of dust entering the room.","c":["affect","effect","accept","except"],"a":0,"why":"Affect is usually a verb meaning to influence. Effect is usually a noun meaning a result.","ctx":[{"t":"p","x":"Questions 9–16 are newly written. Choose the best answer, A–D."}]},{"g":"Word Pairs and Comparisons","q":"All applicants may attend the workshop ___ those who registered late.","c":["except","accept","expect","aspect"],"a":0,"why":"Except means excluding. Accept means to receive or agree to take something."},{"g":"Word Pairs and Comparisons","q":"The measurements were more precise ___ those from the first trial.","c":["then","than","them","that"],"a":1,"why":"Than introduces a comparison. Then refers to time, sequence, or a consequence."},{"g":"Word Pairs and Comparisons","q":"A basic scientific ___ requires repeatable evidence.","c":["principal","principle","principally","principled"],"a":1,"why":"Principle means a rule or fundamental idea. Principal commonly means a school leader or something primary."},{"g":"Word Pairs and Comparisons","q":"A neutral background can ___ the bright lines in the graph.","c":["compliment","complement","complemented","compliments"],"a":1,"why":"Complement means to complete or enhance something. Compliment means to praise; after can, use the base verb complement."},{"g":"Word Pairs and Comparisons","q":"The bicycle remained ___ while the mechanic checked the chain.","c":["stationary","stationery","stationarity","station"],"a":0,"why":"Stationary means not moving. Stationery refers to writing materials such as paper and envelopes."},{"g":"Word Pairs and Comparisons","q":"The report must ___ the source of each statistic.","c":["cite","site","sight","cited"],"a":0,"why":"Cite means to reference a source. Site is a location; sight relates to seeing. After must, use the base verb cite."},{"g":"Word Pairs and Comparisons","q":"The writer made a brief ___ to an earlier experiment without summarizing it.","c":["allusion","illusion","elusion","collusion"],"a":0,"why":"An allusion is an indirect reference. An illusion is a misleading appearance; elusion means evasion, and collusion is secret cooperation."}]},"drills-16":{"session":16,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 16, mixed together like the real exam.","sections":[],"practice":[{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. Neither of the proposals ___ approved by the committee yesterday.","c":["were","was","are","have been"],"a":1,"why":"Neither is singular in formal test grammar. The time marker yesterday requires past tense, so was is correct.","ctx":[{"t":"p","x":"Questions 1–8 are newly written. Choose the best answer, A–D."}]},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. The collection of field notes, maps, and photographs ___ in the archive.","c":["are","were","is","have been"],"a":2,"why":"The subject is collection, not the plural nouns in the prepositional phrase. Collection is singular, so use is."},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. The researchers, along with the laboratory director, ___ preparing the report when the power failed.","c":["was","were","is","has been"],"a":1,"why":"The main subject is researchers. The phrase along with the laboratory director does not change its plural number. The past-progressive form were preparing fits the time frame."},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb form. By the time the team reached the site, the storm ___.","c":["ends","has ended","had ended","will end"],"a":2,"why":"The storm ended before another past event (the team's arrival). The past perfect, had ended, makes that earlier sequence clear."},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. Each of the samples ___ stored at a different temperature during the experiment.","c":["were","have been","was","are"],"a":2,"why":"Each is singular, even when followed by a plural noun in an of-phrase. The sentence describes a past experiment, so was is correct."},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. The report describes how the river ___ after heavy rainfall last spring.","c":["rises","rose","has risen","will rise"],"a":1,"why":"Last spring identifies a completed past event. Rose is the simple-past form and keeps the time reference consistent."},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. A series of tests ___ that the material expands when heated.","c":["show","shows","were showing","have shown"],"a":1,"why":"The subject is the singular phrase a series. The sentence states a general finding, so the simple-present singular verb shows fits."},{"g":"Practice A: verb agreement and tense","q":"Choose the best verb. When the scientist repeated the trial, she discovered that the first reading ___ inaccurate.","c":["is","has been","was","will be"],"a":2,"why":"The sentence narrates past events. Was keeps the discovered result in the same past-time frame."},{"g":"Practice B: word pairs","q":"The new filter may ___ the amount of dust entering the room.","c":["affect","effect","accept","except"],"a":0,"why":"Affect is usually a verb meaning to influence. Effect is usually a noun meaning a result.","ctx":[{"t":"p","x":"Questions 9–16 are newly written. Choose the best answer, A–D."}]},{"g":"Practice B: word pairs","q":"All applicants may attend the workshop ___ those who registered late.","c":["except","accept","expect","aspect"],"a":0,"why":"Except means excluding. Accept means to receive or agree to take something."},{"g":"Practice B: word pairs","q":"The measurements were more precise ___ those from the first trial.","c":["then","than","them","that"],"a":1,"why":"Than introduces a comparison. Then refers to time, sequence, or a consequence."},{"g":"Practice B: word pairs","q":"A basic scientific ___ requires repeatable evidence.","c":["principal","principle","principally","principled"],"a":1,"why":"Principle means a rule or fundamental idea. Principal commonly means a school leader or something primary."},{"g":"Practice B: word pairs","q":"A neutral background can ___ the bright lines in the graph.","c":["compliment","complement","complemented","compliments"],"a":1,"why":"Complement means to complete or enhance something. Compliment means to praise; after can, use the base verb complement."},{"g":"Practice B: word pairs","q":"The bicycle remained ___ while the mechanic checked the chain.","c":["stationary","stationery","stationarity","station"],"a":0,"why":"Stationary means not moving. Stationery refers to writing materials such as paper and envelopes."},{"g":"Practice B: word pairs","q":"The report must ___ the source of each statistic.","c":["cite","site","sight","cited"],"a":0,"why":"Cite means to reference a source. Site is a location; sight relates to seeing. After must, use the base verb cite."},{"g":"Practice B: word pairs","q":"The writer made a brief ___ to an earlier experiment without summarizing it.","c":["allusion","illusion","elusion","collusion"],"a":0,"why":"An allusion is an indirect reference. An illusion is a misleading appearance; elusion means evasion, and collusion is secret cooperation."}]},"parallel-structure":{"session":17,"kind":"Grammar","title":"Parallel Structure","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 200","goal":"Parallel structure repeats the same grammatical pattern for ideas of equal importance. Match nouns with nouns, verbs with verbs, adjectives with adjectives, and equivalent phrases with equivalent phrases.","sections":[{"h":"","blocks":[{"t":"table","x":{"head":["Pattern","Not parallel","Parallel"],"rows":[["Verbs","to plan, measuring, and report","to plan, measure, and report"],["Nouns","planning, measuring, interpretation","planning, measurement, interpretation"],["Adjectives","compact, durable, and operates easily","compact, durable, and easy to operate"],["Paired pattern","not only to reduce waste but also lowering costs","not only to reduce waste but also to lower costs"]]}}]},{"h":"FAST PARALLELISM CHECK","blocks":[{"t":"ul","x":["Find the list or pair, often joined by and, or, but, both…and, either…or, or not only…but also.","Compare the grammatical form of each item.","Read the full sentence after the change; the answer must still fit the meaning."]}]}],"practice":[{"g":"Parallel Structure","q":"The city plans to expand bike lanes, improve bus service, and ___ pedestrian crossings.","c":["repaint","repainting","to repaint","repainted"],"a":0,"why":"Expand, improve, and repaint are parallel base verbs.","ctx":[{"t":"p","x":"All questions below are newly written. Choose the best answer, A–D."}]},{"g":"Parallel Structure","q":"The team was praised for careful planning, accurate measurements, and ___ of the results.","c":["to interpret","interpreting","interpretation","interpreted"],"a":2,"why":"Planning, measurements, and interpretation function as nouns."},{"g":"Parallel Structure","q":"The policy aims not only to reduce waste but also ___ energy consumption.","c":["lowering","to lower","lower","lowered"],"a":1,"why":"The paired pattern is not only to reduce … but also to lower."},{"g":"Parallel Structure","q":"The workshop teaches students how to formulate a hypothesis, collect data, and ___ findings.","c":["analyzing","analyze","analysis","to analyzing"],"a":1,"why":"Formulate, collect, and analyze use the same verb form."},{"g":"Parallel Structure","q":"The device is compact, durable, and ___ to operate.","c":["easy","easily","ease","eased"],"a":0,"why":"Compact, durable, and easy are adjectives describing the device."},{"g":"Parallel Structure","q":"To prepare for the field study, the students packed sample jars, labeled their equipment, and ___ the route.","c":["mapping","mapped","map","to map"],"a":1,"why":"Packed, labeled, and mapped are parallel past-tense verbs."},{"g":"Parallel Structure","q":"A science club writes: “Students will design a test, collect measurements, and ___ their findings to the class.”","c":["presenting","presented","present","presentation of"],"a":2,"why":"Will governs all three base verbs: design, collect, and present."},{"g":"Parallel Structure","q":"A museum exhibit was created “to show how rivers change, explaining why erosion occurs, and to encourage conservation.” Which revision is parallel?","c":["to show how rivers change, explain why erosion occurs, and encourage conservation","showing how rivers change, explain why erosion occurs, and to encourage conservation","to show how rivers change, explaining why erosion occurs, and encouraging conservation","show how rivers change, explaining why erosion occurs, and encouraged conservation"],"a":0,"why":"The shared infinitive marker to governs show, explain, and encourage."}]},"dangling-modifiers":{"session":17,"kind":"Grammar","title":"Dangling and Misplaced Modifiers","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 210","goal":"A modifier describes a noun, pronoun, verb, or phrase. Place it close to the word it modifies.","sections":[{"h":"DANGLING MODIFIER","blocks":[{"t":"p","x":"An introductory phrase often names an action but leaves out the person or thing doing it. The subject immediately after the comma should perform that action."},{"t":"p","x":"Incorrect: “Walking through the greenhouse, the rare orchids caught Maya’s attention.”"},{"t":"p","x":"Correct: “Walking through the greenhouse, Maya noticed the rare orchids.”"}]},{"h":"MISPLACED MODIFIER","blocks":[{"t":"p","x":"A modifier sits beside the wrong word or too far from the word it describes. Move it beside its intended target."},{"t":"p","x":"Unclear: “The report was sent to the editor containing the revised tables.”"},{"t":"p","x":"Clear: “The report containing the revised tables was sent to the editor.”"}]},{"h":"THREE-STEP REPAIR","blocks":[{"t":"ul","x":["Ask who performs the action in the opening phrase.","Check the subject immediately after the comma; name the actor if needed.","Move a misplaced description next to the intended noun or the word it limits."]}]},{"h":"OFFICIAL MAY 2026 EST ALIGNMENT","blocks":[{"t":"p","x":"The official paper includes a directly relevant parallel-construction item: Module 1, Question 14. The correct option is C. The only verbatim excerpt used here is this nine-word phrase:"},{"t":"p","x":"“killing one of his men and wounding the mate”"},{"t":"p","x":"The full item and options are not reproduced because they would exceed the 25-word quotation limit. The item tests parallel participial forms in context. No directly matching May 2026 item specifically testing dangling or misplaced modifiers was identified; those drills are newly written."},{"t":"p","x":"The 2026 description defines Module 1 as Writing, where students edit passages for clarity, style, structure, and grammatical accuracy. These short drills isolate the target skills; apply the same checks to surrounding sentences in a full passage."}]}],"practice":[{"g":"Dangling and Misplaced Modifiers","q":"Fix the dangling modifier: “Walking through the greenhouse, the rare orchids caught Maya’s attention.”","c":["Walking through the greenhouse, the rare orchids caught Maya’s attention.","While walking through the greenhouse, Maya noticed the rare orchids.","The rare orchids, walking through the greenhouse, caught Maya’s attention.","Maya noticed the rare orchids while they walked through the greenhouse."],"a":1,"why":"Maya is the person walking, so she must be the subject after the introductory phrase.","ctx":[{"t":"p","x":"All questions below are newly written. Choose the best answer, A–D."}]},{"g":"Dangling and Misplaced Modifiers","q":"Choose the revision that fixes the dangling modifier while keeping the original structure: “After reviewing the data, the conclusion seemed obvious to the researchers.”","c":["After reviewing the data, the conclusion seemed obvious to the researchers.","After reviewing the data, the researchers found the conclusion obvious.","The conclusion seemed obvious after the researchers reviewed the data.","The conclusion, after reviewing the data, seemed obvious to the researchers."],"a":1,"why":"The researchers reviewed the data; name them as the subject immediately after the comma."},{"g":"Dangling and Misplaced Modifiers","q":"Show clearly that the experiment—not the cafeteria—produced surprising results.","c":["The students discussed the experiment in the cafeteria that had produced surprising results.","The students discussed the experiment, which had produced surprising results, in the cafeteria.","The students discussed the cafeteria, which had produced surprising results, in the experiment.","The students discussed the experiment in the cafeteria, which was surprising."],"a":1,"why":"The clause is placed next to experiment, its intended referent."},{"g":"Dangling and Misplaced Modifiers","q":"Choose the clearest revision: “The report was sent to the editor containing the revised tables.”","c":["The report containing the revised tables was sent to the editor.","The report was sent to the editor, containing the revised tables.","Containing the revised tables, the editor received the report.","The editor containing the revised tables received the report."],"a":0,"why":"Containing the revised tables modifies report, so place it next to report."},{"g":"Dangling and Misplaced Modifiers","q":"Which sentence clearly means nearly all samples were measured?","c":["The researcher almost measured every sample before lunch.","The researcher measured almost every sample before lunch.","The researcher almost every sample measured before lunch.","Almost, the researcher measured every sample before lunch."],"a":1,"why":"Almost sits next to every sample, the words it limits."},{"g":"Dangling and Misplaced Modifiers","q":"Fix the dangling modifier: “Covered in frost, the hikers photographed the mountain at sunrise.”","c":["Covered in frost, the hikers photographed the mountain at sunrise.","The hikers photographed the mountain, which was covered in frost, at sunrise.","The mountain covered in frost photographed the hikers at sunrise.","At sunrise, the hikers, covered in frost, photographed the mountain."],"a":1,"why":"The mountain is covered in frost, so the description belongs next to mountain."},{"g":"Dangling and Misplaced Modifiers","q":"A report says: “The engineer examined the bridge after the inspection. Using a laser scanner, the cracks were measured to the nearest millimeter.” Choose the best revision.","c":["Using a laser scanner, the engineer measured the cracks to the nearest millimeter.","The cracks, using a laser scanner, were measured to the nearest millimeter.","The engineer examined the bridge using a laser scanner, the cracks were measured to the nearest millimeter.","The cracks were measured, using a laser scanner by the bridge, to the nearest millimeter."],"a":0,"why":"The engineer used the scanner; the engineer must be the subject after the introductory phrase."},{"g":"Dangling and Misplaced Modifiers","q":"Fix the dangling modifier: “Having finished the experiment, the results were entered into the logbook.”","c":["Having finished the experiment, the results were entered into the logbook.","After finishing the experiment, the results were entered into the logbook.","Having finished the experiment, the students entered the results into the logbook.","Having finished the experiment, the logbook contained the results."],"a":2,"why":"The students finished the experiment, so name them as the subject."}]},"drills-17":{"session":17,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course (not official EST questions)","goal":"Questions from every lesson in Session 17, mixed together like the real exam.","sections":[],"practice":[{"g":"Practice A: Parallel Structure","q":"The city plans to expand bike lanes, improve bus service, and ___ pedestrian crossings.","c":["repaint","repainting","to repaint","repainted"],"a":0,"why":"Expand, improve, and repaint are parallel base verbs.","ctx":[{"t":"p","x":"All questions below are newly written. Choose the best answer, A–D."}]},{"g":"Practice A: Parallel Structure","q":"The team was praised for careful planning, accurate measurements, and ___ of the results.","c":["to interpret","interpreting","interpretation","interpreted"],"a":2,"why":"Planning, measurements, and interpretation function as nouns."},{"g":"Practice A: Parallel Structure","q":"The policy aims not only to reduce waste but also ___ energy consumption.","c":["lowering","to lower","lower","lowered"],"a":1,"why":"The paired pattern is not only to reduce … but also to lower."},{"g":"Practice A: Parallel Structure","q":"The workshop teaches students how to formulate a hypothesis, collect data, and ___ findings.","c":["analyzing","analyze","analysis","to analyzing"],"a":1,"why":"Formulate, collect, and analyze use the same verb form."},{"g":"Practice A: Parallel Structure","q":"The device is compact, durable, and ___ to operate.","c":["easy","easily","ease","eased"],"a":0,"why":"Compact, durable, and easy are adjectives describing the device."},{"g":"Practice A: Parallel Structure","q":"To prepare for the field study, the students packed sample jars, labeled their equipment, and ___ the route.","c":["mapping","mapped","map","to map"],"a":1,"why":"Packed, labeled, and mapped are parallel past-tense verbs."},{"g":"Practice A: Parallel Structure","q":"A science club writes: “Students will design a test, collect measurements, and ___ their findings to the class.”","c":["presenting","presented","present","presentation of"],"a":2,"why":"Will governs all three base verbs: design, collect, and present."},{"g":"Practice A: Parallel Structure","q":"A museum exhibit was created “to show how rivers change, explaining why erosion occurs, and to encourage conservation.” Which revision is parallel?","c":["to show how rivers change, explain why erosion occurs, and encourage conservation","showing how rivers change, explain why erosion occurs, and to encourage conservation","to show how rivers change, explaining why erosion occurs, and encouraging conservation","show how rivers change, explaining why erosion occurs, and encouraged conservation"],"a":0,"why":"The shared infinitive marker to governs show, explain, and encourage."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Fix the dangling modifier: “Walking through the greenhouse, the rare orchids caught Maya’s attention.”","c":["Walking through the greenhouse, the rare orchids caught Maya’s attention.","While walking through the greenhouse, Maya noticed the rare orchids.","The rare orchids, walking through the greenhouse, caught Maya’s attention.","Maya noticed the rare orchids while they walked through the greenhouse."],"a":1,"why":"Maya is the person walking, so she must be the subject after the introductory phrase.","ctx":[{"t":"p","x":"All questions below are newly written. Choose the best answer, A–D."}]},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Choose the revision that fixes the dangling modifier while keeping the original structure: “After reviewing the data, the conclusion seemed obvious to the researchers.”","c":["After reviewing the data, the conclusion seemed obvious to the researchers.","After reviewing the data, the researchers found the conclusion obvious.","The conclusion seemed obvious after the researchers reviewed the data.","The conclusion, after reviewing the data, seemed obvious to the researchers."],"a":1,"why":"The researchers reviewed the data; name them as the subject immediately after the comma."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Show clearly that the experiment—not the cafeteria—produced surprising results.","c":["The students discussed the experiment in the cafeteria that had produced surprising results.","The students discussed the experiment, which had produced surprising results, in the cafeteria.","The students discussed the cafeteria, which had produced surprising results, in the experiment.","The students discussed the experiment in the cafeteria, which was surprising."],"a":1,"why":"The clause is placed next to experiment, its intended referent."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Choose the clearest revision: “The report was sent to the editor containing the revised tables.”","c":["The report containing the revised tables was sent to the editor.","The report was sent to the editor, containing the revised tables.","Containing the revised tables, the editor received the report.","The editor containing the revised tables received the report."],"a":0,"why":"Containing the revised tables modifies report, so place it next to report."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Which sentence clearly means nearly all samples were measured?","c":["The researcher almost measured every sample before lunch.","The researcher measured almost every sample before lunch.","The researcher almost every sample measured before lunch.","Almost, the researcher measured every sample before lunch."],"a":1,"why":"Almost sits next to every sample, the words it limits."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Fix the dangling modifier: “Covered in frost, the hikers photographed the mountain at sunrise.”","c":["Covered in frost, the hikers photographed the mountain at sunrise.","The hikers photographed the mountain, which was covered in frost, at sunrise.","The mountain covered in frost photographed the hikers at sunrise.","At sunrise, the hikers, covered in frost, photographed the mountain."],"a":1,"why":"The mountain is covered in frost, so the description belongs next to mountain."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"A report says: “The engineer examined the bridge after the inspection. Using a laser scanner, the cracks were measured to the nearest millimeter.” Choose the best revision.","c":["Using a laser scanner, the engineer measured the cracks to the nearest millimeter.","The cracks, using a laser scanner, were measured to the nearest millimeter.","The engineer examined the bridge using a laser scanner, the cracks were measured to the nearest millimeter.","The cracks were measured, using a laser scanner by the bridge, to the nearest millimeter."],"a":0,"why":"The engineer used the scanner; the engineer must be the subject after the introductory phrase."},{"g":"Practice B: Dangling And Misplaced Modifiers","q":"Fix the dangling modifier: “Having finished the experiment, the results were entered into the logbook.”","c":["Having finished the experiment, the results were entered into the logbook.","After finishing the experiment, the results were entered into the logbook.","Having finished the experiment, the students entered the results into the logbook.","Having finished the experiment, the logbook contained the results."],"a":2,"why":"The students finished the experiment, so name them as the subject."}]},"vocabulary-in-context":{"session":2,"kind":"Reading","title":"Vocabulary in Context","source":"Erica Meltzer, The Complete Guide to SAT Reading, Vocabulary in Context, pp. 43–60","goal":"Learn what a Vocabulary-in-Context question asks, how context changes meaning, three ways to solve it, and how to check answer choices.","sections":[{"h":"What Is a Vocabulary-in-Context Question?","blocks":[{"t":"p","x":"The question gives you a word or short phrase from a passage. It asks what the word means in that passage. The important rule from this chapter is:"},{"t":"p","x":"**Context Determines Meaning.**"},{"t":"p","x":"The word may have a common meaning. In the passage, the writer may use a different meaning. Use the text around the word to find the meaning."}]},{"h":"Strategy 1 — Use your own word","blocks":[{"t":"p","x":"Read the sentence. Think of a simple word that has the same meaning. Then find the answer choice that matches your word."}]},{"h":"Strategy 2 — Put each answer into the sentence","blocks":[{"t":"p","x":"Try the choices one by one. Ask: Does this meaning fit the sentence?"}]},{"h":"Strategy 3 — Positive or negative, then check","blocks":[{"t":"p","x":"First decide if the idea is positive or negative. Cross out answers with the wrong feeling. Then test the answers that remain."}]},{"h":"Look at the Context","blocks":[{"t":"ol","x":["Read the sentence with the word.","Read the sentence before and after if you need more help.","Look for clues. Words such as and can show a similar idea. Words such as but can show a different idea.","Make your own simple meaning.","Check the answer choices. If the sentence is not enough, make the context bigger. Read more of the passage."]}]},{"h":"Second Meanings","blocks":[{"t":"p","x":"Many Vocabulary-in-Context questions use a familiar word in a less common meaning. Do not choose the usual meaning automatically."},{"t":"table","x":{"head":["Word","Second meaning","Simple example"],"rows":[["afford","give / provide","The plan affords an opportunity."],["allow","enable / permit","The rule allows students to enter."],["arrest","stop","The medicine arrested the spread."],["assume","take on / accept","She assumed a new role."],["capacity","ability","He has the capacity to learn."],["check","control / stop","The vaccine checked the spread."],["clear","obvious / easy to see","The reason was clear."],["demonstrate","show / establish","The study demonstrates the idea."],["establish","prove / show","The test established the result."],["execute","carry out","They executed the plan."],["exploit","make use of","The company exploited the resource."],["fine","narrow / delicate / highly aware","Fine lines are very thin."],["foil","stop / prevent","The police foiled the plan."],["nature","character / basic quality","We need to understand its nature."],["observe","follow","Observe the rules."],["realize","achieve","They realized their goal."],["reserve","hold back / wait before deciding","Reserve judgment."],["yield","produce / reveal","The experiment yielded results."]]}}]},{"h":"Example A — “stirred”","blocks":[{"t":"p","x":"The passage describes a sport becoming popular. Families come outside to cheer. The feeling is positive. So negative choices can go first. Then test the remaining choices in the sentence. The source uses this as an example of the positive/negative strategy."}]},{"h":"Example B — “registering”","blocks":[{"t":"p","x":"The sentence says that magnetic coils are followed by computers that collect information about cars. A simple meaning such as recording fits. Do not choose a harder-looking word just because it looks more advanced."}]},{"h":"Example C — “closing in on”","blocks":[{"t":"p","x":"The passage says scientists believed they were getting close to understanding the universe. So approaching fits."}]},{"h":"Answer-Choice Traps","blocks":[{"t":"ul","x":["Do not choose the most familiar meaning automatically.","Do not choose a difficult-looking word just because it looks academic.","Do not worry about every word in a wrong answer. Test what you know.","Do not choose an answer only because it contains a second meaning. Check the passage."]}]}],"practice":[{"g":"Quick check","q":"The new rule will **allow** more students to join the club. Which meaning of “allow” fits the sentence?","c":["decorate","confuse","permit","remove"],"a":2,"why":"Here allow means permit or enable. Context decides the meaning."},{"g":"Quick check","q":"The medicine helped **arrest** the spread of the disease. Which meaning of “arrest” fits the sentence?","c":["stop","begin","describe","measure"],"a":0,"why":"Arrest has a second meaning here: stop. Context decides the meaning."},{"g":"Quick check","q":"The scientist **observed** the rules of the experiment. Which meaning of “observed” fits the sentence?","c":["changed","forgot","questioned","followed"],"a":3,"why":"Observe can mean follow, as in observe the rules. Context decides the meaning."},{"g":"Quick check","q":"The evidence helped **establish** the theory. Which meaning of “establish” fits the sentence?","c":["hide","prove","copy","delay"],"a":1,"why":"Establish can mean prove or show. Context decides the meaning."},{"g":"Quick check","q":"The new evidence may **compromise** the plan. Which meaning of “compromise” fits the sentence?","c":["improve it","repeat it","put it at risk","explain it"],"a":2,"why":"Compromise here means put something at risk. Context decides the meaning."}]},"relative-pronouns":{"session":18,"kind":"Grammar","title":"Relative Pronouns","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 218","goal":"Choose who, whom, whose, which, that, where or when by checking the noun being described and the job the word does inside its clause.","sections":[{"h":"Learning targets","blocks":[{"t":"ul","x":["Choose relative pronouns by checking the antecedent and the pronoun's job in the clause.","Review commas, semicolons, colons, dashes, apostrophes, and question marks.","Choose transitions that match the relationship between ideas.","Apply editing skills in passage-based EST Module 1 tasks."]}]},{"h":"What a relative pronoun does","blocks":[{"t":"p","x":"A relative pronoun introduces a clause that describes a noun. First find the noun being described (the antecedent). Then ask what job the missing word does. Where and when are related relative adverbs, not pronouns; they refer to place and time."}]},{"h":"Which word do I use?","blocks":[{"t":"table","x":{"head":["Word","Use it for","Example"],"rows":[["who","People; subject of the clause","The student who spoke first won."],["whom","People; object of a verb/preposition","The student whom I thanked smiled."],["whose","Possession; people or things","The lab whose roof leaked closed."],["which","Things/animals; often nonessential clauses","The sample, which was sealed, arrived."],["that","People/things in essential clauses","The sample that failed was retested."],["where (relative adverb)","Place","The site where we met."],["when (relative adverb)","Time","The year when it began."]]}}]},{"h":"Four-step choice strategy","blocks":[{"t":"ol","x":["Circle the noun that the clause describes.","For a relative pronoun, check the role: subject (who/which/that), object (whom/which/that), or possession (whose). For place/time, use the related adverbs where/when.","Check commas. Essential information identifies the noun and usually has no commas; nonessential information adds extra detail and needs commas.","Read the full sentence. Make sure the clause is complete and the meaning is logical."]}]}],"practice":[{"g":"Relative Pronouns","q":"The ecologist ___ research focused on coastal wetlands presented her findings at the conference.","c":["who","whose","whom","which"],"a":1,"why":"Whose shows possession: the research belongs to the ecologist."},{"g":"Relative Pronouns","q":"The novel, ___ was published in 1924, is still widely read today.","c":["that","who","which","whose"],"a":2,"why":"The commas mark a nonessential clause. Which is the standard choice for a nonessential clause referring to a thing."},{"g":"Relative Pronouns","q":"The volunteers ___ the director thanked stayed after the event to clean the hall.","c":["who","whose","whom","which"],"a":2,"why":"The director thanked the volunteers. The pronoun acts as the object of thanked, so whom fits formal grammar."},{"g":"Relative Pronouns","q":"The museum has a room ___ visitors can examine preserved fossils.","c":["whose","where","whom","which"],"a":1,"why":"Where refers to a place and means 'in which' in this sentence."},{"g":"Relative Pronouns","q":"The students ___ projects won awards will present their work on Friday.","c":["who","whom","which","whose"],"a":3,"why":"Whose shows that the projects belong to the students."},{"g":"Relative Pronouns","q":"The experiment, ___ results surprised the team, was repeated twice.","c":["who","whose","whom","where"],"a":1,"why":"Whose can show possession for things as well as people: the results belong to the experiment."},{"g":"Relative Pronouns","q":"The article describes a scientist ___ developed a low-cost water filter.","c":["whom","whose","who","which"],"a":2,"why":"The relative pronoun is the subject of developed, so who is correct for a person."},{"g":"Relative Pronouns","q":"The manuscript ___ the historian discovered contained several maps.","c":["who","whom","which","whose"],"a":2,"why":"The historian discovered the manuscript. The relative pronoun is the object of discovered and refers to a thing, so which fits."}]},"punct-transitions-review":{"session":18,"kind":"Grammar","title":"Cumulative Review: Punctuation and Transitions","source":"Erica Meltzer, The Ultimate Guide to SAT Grammar, p. 163","goal":"Edit in context: choose punctuation by sentence structure first, then choose a transition by meaning.","sections":[{"h":"Punctuation quick checks","blocks":[{"t":"table","x":{"head":["Mark","Rule and example"],"rows":[["Comma (,)","Use after an introductory element, between list items, around nonessential information, and before FANBOYS joining two complete clauses. Do not join two complete clauses with only a comma."],["Semicolon (;)","Join two closely related independent clauses: The data were incomplete; the team ran another trial."],["Colon (:)","Place after a complete clause to introduce a list or explanation: The team needed three tools: a ruler, a scale, and a timer."],["Dash (—)","Use one or a pair for a strong interruption or inserted detail. Keep paired dashes balanced."],["Apostrophe (’)","Use for possession or contractions, not ordinary plurals: the researchers’ notes; it’s = it is."],["Question mark (?)","Use after a direct question. An indirect question usually ends with a period."]]}}]},{"h":"Transition logic","blocks":[{"t":"ul","x":["Addition: also, furthermore. Contrast: however, nevertheless. Cause/result: therefore, as a result. Example: for instance. Sequence: first, next, finally.","Name the relationship between ideas before looking at choices. A familiar transition can still be wrong if its logic does not fit.","When therefore or however joins independent clauses, check punctuation: often a semicolon before it and a comma after it."]}]},{"h":"Exam transfer: edit in context","blocks":[{"t":"p","x":"The 2026 EST Literacy test integrates Writing, Reading, and Reading-and-Writing tasks. In Module 1, the question sits inside a passage. Read the sentence before and after the target, identify the grammatical job or logical relationship, then select the smallest change that fixes the issue."},{"t":"p","x":"Official exam references (question numbers only): Module 1 Q23 tests relative-pronoun choice; Q2 comma use in a list; Q22 punctuation choice; Q16 and Module 3 Q18 logical transitions. The official wording and answers are not reproduced."}]}],"practice":[{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence that correctly joins two independent clauses.","c":["The rain stopped, the teams returned to the field.","The rain stopped; the teams returned to the field.","The rain stopped: and the teams returned to the field.","The rain stopped the teams, returned to the field."],"a":1,"why":"A semicolon can join two closely related independent clauses. A comma alone creates a comma splice."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Which sentence uses a colon correctly?","c":["The committee needed: three items for the trip.","The committee needed three items: a map, a compass, and a first-aid kit.","The committee: needed three items, a map and compass.","The committee needed three items, a map: a compass, and a first-aid kit."],"a":1,"why":"A colon follows a complete clause and introduces an explanation or list."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence with correct punctuation around a nonessential relative clause.","c":["The Nile which flows north, crosses several countries.","The Nile, which flows north crosses several countries.","The Nile, which flows north, crosses several countries.","The Nile which flows north crosses, several countries."],"a":2,"why":"The nonessential clause adds extra information, so commas must appear on both sides."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Which sentence uses a question mark correctly?","c":["The researcher asked where the sensors were placed?","Where did the researchers place the sensors?","The question was, where did the researchers place the sensors.","The researchers asked, where the sensors were placed?"],"a":1,"why":"A direct question takes a question mark. An indirect question normally ends with a period."},{"g":"Cumulative Review: Punctuation and Transitions","q":"The ___ presentations were selected for the final round.","c":["students","student's","students'","students's"],"a":2,"why":"Students is plural; students' shows that the presentations belong to multiple students."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence that uses paired dashes correctly.","c":["The new telescope—designed for deep-space observation—will launch in June.","The new telescope—designed for deep-space observation, will launch in June.","The new telescope, designed for deep-space observation—will launch in June.","The new telescope—designed for deep-space observation will launch—in June."],"a":0,"why":"The two dashes open and close the inserted description."},{"g":"Cumulative Review: Punctuation and Transitions","q":"The first trial produced inconsistent results. ___, the researchers adjusted the measurement procedure before testing again.","c":["However","Similarly","As a result","For example"],"a":2,"why":"The second sentence describes a response caused by the inconsistent results, so As a result shows cause and effect."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence that uses a transition and its punctuation correctly.","c":["The sample was small, therefore the team repeated the study.","The sample was small; therefore, the team repeated the study.","The sample was small therefore; the team repeated the study.","The sample was small: therefore the team, repeated the study."],"a":1,"why":"Use a semicolon before a conjunctive adverb joining independent clauses and a comma after therefore."}]},"drills-18":{"session":18,"kind":"Practice","title":"Mixed Session Review","source":"Original practice written for this course","goal":"Relative pronouns, punctuation and transitions together.","sections":[],"practice":[{"g":"Relative Pronouns","q":"The ecologist ___ research focused on coastal wetlands presented her findings at the conference.","c":["who","whose","whom","which"],"a":1,"why":"Whose shows possession: the research belongs to the ecologist."},{"g":"Relative Pronouns","q":"The novel, ___ was published in 1924, is still widely read today.","c":["that","who","which","whose"],"a":2,"why":"The commas mark a nonessential clause. Which is the standard choice for a nonessential clause referring to a thing."},{"g":"Relative Pronouns","q":"The volunteers ___ the director thanked stayed after the event to clean the hall.","c":["who","whose","whom","which"],"a":2,"why":"The director thanked the volunteers. The pronoun acts as the object of thanked, so whom fits formal grammar."},{"g":"Relative Pronouns","q":"The museum has a room ___ visitors can examine preserved fossils.","c":["whose","where","whom","which"],"a":1,"why":"Where refers to a place and means 'in which' in this sentence."},{"g":"Relative Pronouns","q":"The students ___ projects won awards will present their work on Friday.","c":["who","whom","which","whose"],"a":3,"why":"Whose shows that the projects belong to the students."},{"g":"Relative Pronouns","q":"The experiment, ___ results surprised the team, was repeated twice.","c":["who","whose","whom","where"],"a":1,"why":"Whose can show possession for things as well as people: the results belong to the experiment."},{"g":"Relative Pronouns","q":"The article describes a scientist ___ developed a low-cost water filter.","c":["whom","whose","who","which"],"a":2,"why":"The relative pronoun is the subject of developed, so who is correct for a person."},{"g":"Relative Pronouns","q":"The manuscript ___ the historian discovered contained several maps.","c":["who","whom","which","whose"],"a":2,"why":"The historian discovered the manuscript. The relative pronoun is the object of discovered and refers to a thing, so which fits."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence that correctly joins two independent clauses.","c":["The rain stopped, the teams returned to the field.","The rain stopped; the teams returned to the field.","The rain stopped: and the teams returned to the field.","The rain stopped the teams, returned to the field."],"a":1,"why":"A semicolon can join two closely related independent clauses. A comma alone creates a comma splice."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Which sentence uses a colon correctly?","c":["The committee needed: three items for the trip.","The committee needed three items: a map, a compass, and a first-aid kit.","The committee: needed three items, a map and compass.","The committee needed three items, a map: a compass, and a first-aid kit."],"a":1,"why":"A colon follows a complete clause and introduces an explanation or list."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence with correct punctuation around a nonessential relative clause.","c":["The Nile which flows north, crosses several countries.","The Nile, which flows north crosses several countries.","The Nile, which flows north, crosses several countries.","The Nile which flows north crosses, several countries."],"a":2,"why":"The nonessential clause adds extra information, so commas must appear on both sides."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Which sentence uses a question mark correctly?","c":["The researcher asked where the sensors were placed?","Where did the researchers place the sensors?","The question was, where did the researchers place the sensors.","The researchers asked, where the sensors were placed?"],"a":1,"why":"A direct question takes a question mark. An indirect question normally ends with a period."},{"g":"Cumulative Review: Punctuation and Transitions","q":"The ___ presentations were selected for the final round.","c":["students","student's","students'","students's"],"a":2,"why":"Students is plural; students' shows that the presentations belong to multiple students."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence that uses paired dashes correctly.","c":["The new telescope—designed for deep-space observation—will launch in June.","The new telescope—designed for deep-space observation, will launch in June.","The new telescope, designed for deep-space observation—will launch in June.","The new telescope—designed for deep-space observation will launch—in June."],"a":0,"why":"The two dashes open and close the inserted description."},{"g":"Cumulative Review: Punctuation and Transitions","q":"The first trial produced inconsistent results. ___, the researchers adjusted the measurement procedure before testing again.","c":["However","Similarly","As a result","For example"],"a":2,"why":"The second sentence describes a response caused by the inconsistent results, so As a result shows cause and effect."},{"g":"Cumulative Review: Punctuation and Transitions","q":"Choose the sentence that uses a transition and its punctuation correctly.","c":["The sample was small, therefore the team repeated the study.","The sample was small; therefore, the team repeated the study.","The sample was small therefore; the team repeated the study.","The sample was small: therefore the team, repeated the study."],"a":1,"why":"Use a semicolon before a conjunctive adverb joining independent clauses and a comma after therefore."}]},"targeted-revision":{"session":19,"kind":"Revision","title":"Targeted Revision Protocol","source":"Original teacher handout, Session 19","goal":"Turn your diagnostic mock results into a precise plan: find your two weakest skills, fix them, and prove the fix.","sections":[{"h":"Targeted revision protocol","blocks":[{"t":"ol","x":["Score each module separately: Module 1 /35, Module 2 /25, Module 3 /25.","Sort errors into: sentence boundaries; punctuation; agreement/tense/pronouns; transitions and organization; concision/style; main idea/details; inference/evidence; purpose/structure; synthesis/data; short-stimulus editing.","Prioritize the two categories with the most errors. Re-teach the rule, model one example, then complete 5–8 new questions.","For reading errors, underline the exact textual evidence before choosing an answer.","Reattempt missed questions after 24–48 hours without looking at the key. Track repeated errors."]}]},{"h":"Score interpretation (diagnostic only)","blocks":[{"t":"ul","x":["76–85 correct: strong readiness; focus on timing and missed skills.","64–75 correct: generally secure; target recurring patterns.","51–63 correct: developing; revise the two weakest skill groups before another full mock.","0–50 correct: rebuild core skills in short lessons, then retry selected modules."]},{"t":"note","x":"These bands are instructional guidelines for this practice set, not official EST score conversions."}]}],"testId":"s19-diagnostic-mock"}});})();
